            new WorldGeneralInfo("公孙模", "公孙模", "公孫模 Gongsun Mo", "公孙康部将（建安中）", "约204年与张敞收集乐浪南部遗民、兴兵伐韩濊，开置带方郡；190年时尚无事迹，作在野隐士。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("张敞", "张敞", "張敞 Zhang Chang", "公孙康部将（建安中）", "与公孙模同往带方，收集遗民、伐韩濊。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("王烈", "王烈（字彦方）", "王烈 Wang Lie", "平原名士，避董卓之乱至辽东", "（《三国志·管宁传》称“平原王烈”，《后汉书·独行传》作太原人）师从陈寔，以德化乡里；在辽东为公孙度长史（一说为商贾以自秽辞官），使“强不凌弱，众不暴寡”；曹操屡征，公孙氏不遣。", null, 141, 218, "yes", "han", "m"),
            new WorldGeneralInfo("管宁", "管宁（字幼安）", "管寧 Guan Ning", "北海名士，避乱辽东三十七年", "闻公孙度令行海外，与邴原、王烈同至辽东，公孙度虚馆以候；讲诗书、陈俎豆，化民成俗。", null, 158, 241, "yes", "han", "m"),
            new WorldGeneralInfo("邴原", "邴原（字根矩）", "邴原 Bing Yuan", "北海名士，避乱辽东", "与管宁、王烈并称“辽东三杰”，后归曹操。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("国渊", "国渊（字子尼）", "國淵 Guo Yuan", "郑玄弟子，随管宁、邴原避乱辽东", "后归曹操为司空掾属，主持屯田有功。", "屯田有功，政治偏高。", null, null, "yes", "han", "m"),
            new WorldGeneralInfo("凉茂", "凉茂（字伯方）", "涼茂 Liang Mao", "曹操所任乐浪太守，被公孙度扣留", "不屈于公孙度；劝阻公孙康袭邺；后为魏郡太守、甘陵相，所在有治绩。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("故国川王", "故国川王（高男武；《三国志》作伊夷模）", "고국천왕 Gogukcheon (Go Nammu)", "高句丽第9代王（179—197在位）", "《三国史记》称其身长九尺、力能扛鼎；184年亲率精骑于坐原大破汉辽东太守军；191年平外戚之乱，举贤不拘出身；194年创赈贷法。", null, null, 197, "yes", "korea", "m"),
            new WorldGeneralInfo("延优", "高延优（即位后为山上王）", "고연우 Go Yeonu (Sansang)", "王弟；197年即位为山上王", "197年王兄卒，得王后于氏之助抢先即位并娶于氏；198年筑丸都城，209年移都，善权谋。", null, null, 227, "yes", "korea", "m"),
            new WorldGeneralInfo("发歧", "高发歧（《三国志》作拔奇）", "고발기 Go Balgi", "新大王之子、王族", "197年争位失败，携妻子投辽东公孙度，借兵三万攻国内城（《三国史记》；《三国志》则记作拔奇于建安中投公孙康），为罽须所败而自杀；性情粗率。", "性情粗率，开局忠诚偏低。", null, 197, "yes", "korea", "m"),
            new WorldGeneralInfo("罽须", "高罽须", "고계수 Go Gyesu", "王子（新大王之子，延优之弟）", "184年奉命领兵拒汉辽东太守；197年率军击败发歧与辽东援军，为高句丽王族中最能战者。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("於畀留", "於畀留（于畀留）", "어비류 Eo Biryu", "中畏大夫、沛者；王后于氏亲族", "与左可虑执国权柄，子弟恃势掠夺；190年王欲诛之，遂与四椽那谋叛，191年攻王都被平定。", "开局忠诚低。", null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("左可虑", "左可虑", "좌가려 Jwa Garyeo", "评者；王后于氏亲族", "191年四月聚众攻王都，为故国川王征畿内兵马所平；为叛乱主谋。", "武力略高。", null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("优居", "优居", "우거 Ugeo", "大加（大贵族）", "《三国志》：公孙度雄海东时，高句丽王伯固遣大加优居、主簿然人助度击富山贼，破之。", "驻沃沮为游戏安排。", null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("然人", "然人", "연인 Yeonin", "主簿", "与优居同助公孙度击富山贼；文职，智政中等。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("乙巴素", "乙巴素", "을파소 Eul Paso", "西鸭渌谷左勿村农夫；191年拜国相", "琉璃王大臣乙素之孙，“性质刚毅，智虑渊深”，经晏留推荐由布衣拜国相，至203年卒，政教清明——高句丽的“卧龙”，作在野隐士。", null, null, 203, "yes", "korea", "m"),
            new WorldGeneralInfo("晏留", "晏留", "안류 An Yu", "东部人；191年四部共举，后为于台", "王命四部举贤，众举晏留，晏留自辞而荐乙巴素。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("高优娄", "高优娄", "고우루 Go Uru", "203年继乙巴素为国相", "山上王、东川王两朝国相，230年卒。", null, null, 230, "yes", "korea", "m"),
            new WorldGeneralInfo("尉仇台", "尉仇台", "위구태 Wigutae", "夫余王", "汉末改属辽东，娶公孙度宗女以结援，周旋于高句丽与鲜卑之间；生卒不详。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("简位居", "简位居", "간위거 Ganwigeo", "尉仇台之子，继位为夫余王", "尉仇台死后立；无嫡子，有孽子麻余。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("肖古王", "肖古王（一作素古王）", "초고왕 Chogo", "百济第5代王（166—214在位）", "188年攻新罗母山城、189年战于狗壤、190年袭圆山乡围缶谷城并于蛙山以佯退大破仇道；214年遣真果袭靺鞨石门城。", null, null, 214, "yes", "korea", "m"),
            new WorldGeneralInfo("仇首", "仇首（一作贵须）", "구수 Gusu", "肖古王长子，214年即位", "《三国史记》称其身长七尺、威仪秀异；216年破靺鞨于沙道城，222年遣兵入新罗牛头州，于熊谷大破新罗伊伐飡忠萱所率五千兵。", null, null, 234, "yes", "korea", "m"),
            new WorldGeneralInfo("真果", "真果", "진과 Jin Gwa", "北部人，百济将领", "214年领兵一千袭取靺鞨石门城；190年时无事迹，作在野隐士。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("古尔", "古尔（古尔王）", "고이왕 Goi", "《三国史记》称盖娄王次子、肖古王之弟；234—286在位", "即位后设六佐平、十六官等，整顿律令，被视为百济国家体制的奠基者。", "政治偏高。", null, 286, "yes", "korea", "m"),
            new WorldGeneralInfo("伐休", "伐休尼师今（昔伐休）", "벌휴 이사금 Beolhyu Isageum", "斯卢（新罗）第9代王（184—196在位）", "《三国史记》称其能占风云、预知水旱丰俭、又知人邪正，国人谓之圣；185年遣军灭召文国。", "武力弱、智力高。", null, 196, "yes", "korea", "m"),
            new WorldGeneralInfo("仇道", "金仇道", "김구도 Kim Gudo", "波珍飡、左军主", "185年与仇须兮为左右军主讨召文国；188—189年拒百济于母山城、狗壤；190年追百济至蛙山中伏，贬缶谷城主；后追封葛文王，金氏首位国王味邹之父。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("仇须兮", "仇须兮", "구수혜 Gusuhye", "一吉飡、右军主", "185年为右军主，与仇道同讨召文国。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("薛支", "薛支", "설지 Seolji", "190年代仇道为左军主", "仇道蛙山失利后受命为左军主，掌新罗主力。", null, null, null, "yes", "korea", "m"),
            new WorldGeneralInfo("奈解", "奈解（昔奈解）", "내해 Naehae", "伐休之孙（伊买之子），196年即位", "《三国史记》称其容仪雄伟、有俊才；209年遣太子于老救加罗、破浦上八国。", null, null, 230, "yes", "korea", "m"),
            new WorldGeneralInfo("昔于老", "昔于老", "석우로 Seok Uro", "奈解之子；伊飡、舒弗邯", "209年救加罗，231年灭甘文国，233年于沙道以火攻大破倭兵，又平沙梁伐国；后因戏言触怒倭人，被焚杀（249年，一说253年）。新罗早期第一名将。", null, null, 249, "yes", "korea", "m"),
            new WorldGeneralInfo("利音", "利音（一作奈音）", "이음 Ieum", "王子；伊伐飡、兼知内外兵马事", "207年拜伊伐飡掌内外兵马，209年随于老救加罗，220年卒。", null, null, 220, "yes", "korea", "m"),
            new WorldGeneralInfo("助贲", "助贲（昔助贲）", "조분 Jobun", "伐休之孙（骨正之子），230—247在位", "伐休卒时年幼不得立，230年继奈解为王；在位时于老东征西讨。", null, null, 247, "yes", "korea", "m"),
            new WorldGeneralInfo("首露王", "首露王（金首露）", "수로왕 Suro", "金官伽倻始祖（传42—199在位）", "据《驾洛国记》传说自龟旨峰金卵而生、在位一百五十八年；又传曾受新罗之请仲裁音汁伐国与悉直谷国疆界。", "能力依其建国与“贤明”传说而定。", null, 199, "legendary", "korea", "m"),
            new WorldGeneralInfo("居登", "居登王", "거등왕 Geodeung", "首露王与许黄玉之子，199年嗣位", "传199—253年在位（一说至259年）；事迹仅见王系传说。", null, null, 253, "legendary", "korea", "m"),
            new WorldGeneralInfo("卑弥呼", "卑弥呼（亲魏倭王）", "卑弥呼 Himiko（ひみこ）", "倭女王，邪马台国王", "倭国大乱后被诸国共立，事鬼道、能惑众，年已长大无夫婿，有男弟佐治国；239年遣使魏，受封亲魏倭王、金印紫绶；约248年卒。", "智力、政治高而武力极低。", null, 248, "yes", "wa", "f"),
            new WorldGeneralInfo("难升米", "难升米", "難升米 Nashime（なしめ）", "大夫、率善中郎将", "239年为正使赴带方、洛阳，受率善中郎将银印青绶；245年魏赐黄幢，247年张政持诏书黄幢拜假难升米、为檄告喻，主持对狗奴战事。事迹见于239—247年，按扩展时间窗收录。", null, null, null, "yes", "wa", "m"),
            new WorldGeneralInfo("伊声耆", "伊声耆", "伊聲耆 Iseki（いせき）", "大夫", "243年与掖邪狗等八人使魏，献生口、倭锦等。", null, null, null, "yes", "wa", "m"),
            new WorldGeneralInfo("都市牛利", "都市牛利", "都市牛利 Toshi Gori（としごり）", "次使、率善校尉", "239年随难升米使魏，受率善校尉。", "驻伊都（郡使往来常驻之所）为游戏安排。", null, null, "yes", "wa", "m"),
            new WorldGeneralInfo("掖邪狗", "掖邪狗", "掖邪狗 Yakuyako（やくやこ）", "大夫、率善中郎将", "243年使魏受率善中郎将印绶；卑弥呼死后台与遣其率二十人送张政还魏。", "驻投马为游戏安排。", null, null, "yes", "wa", "m"),
            new WorldGeneralInfo("载斯乌越", "载斯乌越", "載斯烏越 Sashiao（さしあお）", "倭使", "247年诣带方郡陈说与狗奴国相攻之状（原文“遣倭载斯乌越等”，一说为载斯、乌越二人）。", null, null, null, "yes", "wa", "m"),
            new WorldGeneralInfo("卑弥弓呼", "卑弥弓呼", "卑弥弓呼 Himikuko（ひみくこ）", "狗奴国男王", "与倭女王卑弥呼“素不和”，247年前后相攻，迫使卑弥呼遣使求援于魏。", "以敢于与女王国对抗定武力。", null, null, "yes", "wa", "m"),
            new WorldGeneralInfo("狗古智卑狗", "狗古智卑狗", "狗古智卑狗 Kukuchihiko（くくちひこ）", "狗奴国之官", "《魏志倭人传》：“其官有狗古智卑狗”；九州说以为“菊池彦”之音译。", "按狗奴国主将定能力。", null, null, "yes", "wa", "m"),
            new WorldGeneralInfo("魁头", "魁头", "Kuitou", "鲜卑大人（檀石槐之孙、和连兄子）", "灵帝末年和连进攻北地时中弩身亡，儿子骞曼年幼，由兄子魁头继立；骞曼长大后与他争国，部众离散。能守住旧地，却不能重新整合诸部。", "武力中上、政略一般。", null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("骞曼", "骞曼", "Qianman", "鲜卑王子（和连之子）", "和连之子，长大后与魁头争夺鲜卑共主之位，导致“众遂离散”。", "忠诚设低。", null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("步度根", "步度根", "Budugen", "鲜卑大人（魁头之弟，后继立）", "魁头死后继立，但“众稍衰弱”；建安年间通过阎柔向曹操进贡，魏初受封为王；233年被轲比能诱使叛魏，兵败后被比能所杀。", null, null, 233, "yes", "steppe", "m"),
            new WorldGeneralInfo("扶罗韩", "扶罗韩", "Fuluohan", "鲜卑大人（步度根中兄，别拥众数万）", "另外拥有部众数万，自为大人；218年领万余骑到桑干迎接叛乱的代郡乌丸能臣氐，却在盟会上被轲比能杀死。勇猛而少谋。", null, null, 218, "yes", "steppe", "m"),
            new WorldGeneralInfo("轲比能", "轲比能", "Kebineng", "小种鲜卑大人（后为漠南霸主）", "以“勇健，断法平端，不贪财物”被推为大人；袁绍据河北后，大批汉人投奔他，教作兵器铠楯，部众颇学文字，“勒御部众，拟则中国”。后来控弦十余万骑，235年被幽州刺史王雄派韩龙刺杀。190年尚未崛起，设为在野。", null, null, 235, "yes", "steppe", "m"),
            new WorldGeneralInfo("泄归泥", "泄归泥", "Xieguini", "鲜卑大人（扶罗韩之子）", "218年父亲被轲比能所杀后，率部众归附比能；233年秦朗北征时，他叛离步度根、比能，归降魏朝。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("素利", "素利", "Suli", "东部鲜卑大人（后为魏归义王）", "檀石槐时已是东部大人；建安年间通过阎柔进贡、通市，曹操表奏封王，魏文帝立为归义王；与轲比能长期相攻，太和二年（228年）去世。部众比轲比能还多，却“道远初不为边患”。", "能力偏向守成。", null, 228, "yes", "steppe", "m"),
            new WorldGeneralInfo("弥加", "弥加", "Mijia", "东部鲜卑大人（后为魏归义王）", "檀石槐所置东部大人之一，后来与素利同被魏文帝立为归义王。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("阙机", "阙机（厥机）", "Queji", "东部鲜卑大人", "《魏书》作阙机，《三国志》作厥机；建安年间受曹操表奏封王，去世后儿子沙末汗嗣立为亲汉王（220年以前）。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("沙末汗", "沙末汗", "Shamohan", "东部鲜卑亲汉王（厥机之子）", "厥机死后被立为亲汉王，延康初年（220年）与素利、弥加各自遣使献马。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("成律归", "成律归", "Chengliugui", "东部鲜卑王（素利之弟，摄政）", "太和二年（228年）素利去世，儿子年幼，由弟弟成律归为王，代管部众。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("莫护跋", "慕容莫护跋", "Muhuba", "慕容部首领（魏率义王）", "魏初率诸部从塞外迁入辽西；238年随司马懿讨伐公孙渊立功，拜率义王，在棘城之北立国；因喜好步摇冠，被称为“步摇”，音讹为“慕容”。生年不详，推测约生于190年代。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("丘力居", "丘力居", "Qiuliju", "辽西乌丸大人（自称王）", "统辖五千余落，“皆有计策勇健”；187年与张纯、张举一同叛乱，寇掠青、徐、幽、冀四州，在辽西管子城围困公孙瓒二百余日；189年接受刘虞招抚归降。初平年间（190—193）去世，卒年按191年计。", null, null, 191, "yes", "steppe", "m"),
            new WorldGeneralInfo("蹋顿", "蹋顿", "Tadun", "乌丸大人（丘力居从子，后总摄三郡乌桓、称单于）", "“有武略”，代丘力居而立，总摄三郡乌桓；出兵助袁绍击破公孙瓒，被袁绍假托诏命授予单于印绶；207年白狼山之战中被张辽斩杀。", null, null, 207, "yes", "steppe", "m"),
            new WorldGeneralInfo("苏仆延", "苏仆延（速仆丸）", "Supuyan", "辽东属国乌丸大人（峭王）", "统辖千余落，自称峭王；后来与难楼共奉楼班为单于；207年随袁尚、袁熙投奔辽东，被公孙康所杀。", null, null, 207, "yes", "steppe", "m"),
            new WorldGeneralInfo("乌延", "乌延", "Wuyan", "右北平乌丸大人（汗鲁王）", "统辖八百余落，自称汗鲁王，受袁绍单于印绶；207年在辽东被公孙康所杀。", null, null, 207, "yes", "steppe", "m"),
            new WorldGeneralInfo("难楼", "难楼（那楼）", "Nanlou", "上谷乌丸大人（自称王，后称单于）", "统辖九千余落，是诸部中最大的一支；受袁绍单于印绶，后与苏仆延共奉楼班为单于；207年十一月曹操自柳城还至易水，“上郡乌丸行单于那楼”率名王来贺（“上郡”一般认为即上谷，那楼即难楼）。190年时并不隶属丘力居。", "不隶属丘力居，故忠诚设低。", null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("楼班", "楼班", "Louban", "乌丸单于（丘力居之子）", "丘力居死时年纪尚小，由蹋顿代立；长大后被难楼、苏仆延奉为单于，蹋顿退为王；207年在辽东被公孙康所杀。", null, null, 207, "yes", "steppe", "m"),
            new WorldGeneralInfo("寇娄敦", "寇娄敦", "Kouloudun", "右北平乌丸单于（魏时）", "曹魏时的右北平乌丸单于，派弟弟阿罗槃入朝进贡；景初元年（237年）毌丘俭征辽东时，与辽西乌丸都督护留等率五千余人归降。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("阎柔", "阎柔", "Yan Rou", "汉人豪杰（后为护乌丸校尉）", "广阳人，少年时陷没在乌丸、鲜卑中，深得胡人信任；195年借鲜卑之力杀护乌桓校尉邢举而代之，与鲜于辅合兵在鲍丘大破公孙瓒；官渡之战时归附曹操，拜护乌丸校尉、关内侯。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("普富卢", "普富卢", "Pufulu", "代郡乌丸行单于", "207年十一月曹操北征乌桓还至易水，以代郡乌丸行单于身份率名王来贺；216年五月又与其侯王来朝。代郡与上谷相邻，放在宁城。", "由在野改为在任：与难楼同驻宁城，名义上归附丘力居（190年时的身份不详，忠诚偏低）。", null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("能臣氐", "能臣氐（无臣氐）", "Nengchendi", "代郡乌丸首领", "218年叛魏，先求依附扶罗韩，又改招轲比能，导致扶罗韩在盟会上被杀。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("於夫罗", "持至尸逐侯单于 於夫罗（於扶罗）", "Yufuluo", "南匈奴单于（流亡中）", "羌渠单于之子；188年父亲被国人所杀后即位，国人却另立须卜骨都侯，拒不接纳他；他赴洛阳申诉，灵帝死后与白波军合兵寇掠河内，回国不成，只好留在河东平阳；190—191年与张杨屯驻漳水，后劫持张杨背叛袁绍、屯兵黎阳；192年在内黄被曹操击破，193年随袁术屯封丘，匡亭之战再败；195年去世。", null, null, 195, "yes", "steppe", "m"),
            new WorldGeneralInfo("呼厨泉", "呼厨泉单于", "Huchuquan", "南匈奴王族（於夫罗之弟，195年继为单于）", "於夫罗死后继任单于；216年入朝曹操，被留在邺城，南匈奴就此分为五部。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("去卑", "右贤王 去卑", "Qubei", "南匈奴右贤王（呼厨泉之叔）", "据《北史·破六韩常传》为羌渠单于之弟、呼厨泉之叔。195—196年护送汉献帝东归洛阳；216年呼厨泉被留在邺城后，他奉命回国监国。美稷单于庭190年不归於夫罗，因此放在平阳。", null, null, null, "yes", "steppe", "m"),
            new WorldGeneralInfo("刘豹", "刘豹", "Liu Bao", "南匈奴左贤王（於夫罗之子，刘渊之父）", "195年任左贤王；216年为左部帅，居住在太原兹氏；279年去世。他的世系和年寿有学者存疑。", "由在野改为在任：作为於夫罗之子随父驻平阳（195年才任左贤王）。", null, 279, "yes", "steppe", "m"),
            new WorldGeneralInfo("拓跋力微", "拓跋力微（北魏始祖神元皇帝）", "Tuoba Liwei", "索头鲜卑拓跋部首领", "《魏书·序纪》记载他生于174年、220年继立；起初依附没鹿回部窦宾，后来北居长川，258年迁到盛乐，诸部尽数归附；261年派儿子沙漠汗入魏为质，277年因卫瓘的离间忧愤而死。《魏书》称他享年104岁，带有传说成分。", null, 174, 277, "yes", "steppe", "m"),
            new WorldGeneralInfo("童格罗伽", "童格罗伽天子", "Tomgraka", "鄯善王（佉卢文书称“大王、众王之王、天子”）", "佉卢文书王统中排在陀阇迦之前的鄯善王，王号“大王、众王之王、天子”与贵霜王号相近；确切年代未定。", "中文无通行译名，“童格罗伽”为音译；能力取守成之君。", null, null, "yes", "tarim", "m"),
            new WorldGeneralInfo("陀阇迦", "陀阇迦", "Tajaka", "鄯善王（佉卢文书）", "佉卢文书所见的鄯善王，在位约3年；Brough推定他的元年约在230—235年（长泽和俊的推定更早）。按此年代生年可能接近205年，属勉强收录。", null, null, null, "yes", "tarim", "m"),
            new WorldGeneralInfo("贝比耶", "贝比耶", "Pepiya", "鄯善王（佉卢文书）", "佉卢文书所见的鄯善王，在陀阇迦之后、安归迦之前，在位约8年；按Brough年代约在230年代末至240年代，另一说约245—253年在位，生年可能接近或略晚于205年，属勉强收录。", null, null, null, "yes", "tarim", "m"),
            new WorldGeneralInfo("安国", "于阗王 安国", "Anguo", "于阗王", "于阗王建之子；152年西域长史王敬杀死建，侯将输僰又杀王敬，国人杀输僰后拥立安国；175年进攻拘弥，大破其国并杀死拘弥王，戊己校尉与西域长史只得发兵另立定兴。此后史书再无记载，190年是否在世不详。", null, null, null, "yes", "tarim", "m"),
            new WorldGeneralInfo("和得", "疏勒王 和得（和德）", "Hede", "疏勒王（篡位）", "《后汉书》：168年疏勒王（汉大都尉，一般认为即臣磐）在狩猎时被季父和得射杀，和得自立为王；170年凉州刺史孟佗派任涉、曹宽、张晏率焉耆、龟兹、车师前后部兵三万余人讨伐，围攻桢中城四十余日不能攻下。《曹全碑》则说“和德弑父篡位”，被曹全征讨后“面缚归死”。此后“疏勒王连相杀害”，190年是否仍在位甚至是否在世都很可疑。", null, null, null, "yes", "tarim", "m"),
            new WorldGeneralInfo("阿罗多", "车师后部王 阿罗多", "Aluoduo", "车师后部王", "153年与戊部候严皓不和，起兵围攻汉朝屯田，兵败逃入北匈奴；后来从匈奴返回，与卑君争国，汉朝又立他为王。最后见于153年前后，190年是否在世不详。", null, null, null, "yes", "tarim", "m"),
            new WorldGeneralInfo("壹多杂", "壹多杂", "Yiduoza", "车师后部王（曹魏时）", "《魏略·西戎传》记载：车师后部王治于赖城，魏赐其王壹多杂守魏侍中，号大都尉，并授魏王印。", null, null, null, "yes", "tarim", "m"),
            new WorldGeneralInfo("张恭", "张恭", "Zhang Gong", "敦煌郡功曹（后为西域戊己校尉）", "敦煌人，素有学行，任郡功曹；建安末年太守马艾死在任上，郡人推举他代行长史之事；他派儿子张就向曹操请派太守，并抵御酒泉黄华、张掖张进之乱；魏文帝拜他为西域戊己校尉、关内侯。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("士燮", "士燮（字威彦）", "士燮 Shi Xie / Sĩ Nhiếp", "交趾太守（187起）；后为绥南中郎将、董督七郡，降吴拜卫将军、龙编侯", "少游学京师、治《左氏春秋》并为之注；袁徽称他“处大乱之中，保全一郡，二十余年疆场无事”，越南尊为“南交学祖”。学问与治绩突出而无战功。", "政治高、智力中上、武力平平（对照刘表、陆康校准）。", 137, 226, "yes", "han", "m"),
            new WorldGeneralInfo("士壹", "士壹", "士壹 Shi Yi / Sĩ Nhất", "士燮之弟；郡督邮 → 合浦太守、偏将军、都乡侯", "侍送刺史丁宫勤恪，被司徒丁宫、黄琬先后辟用；董卓作乱（189—190）时逃归乡里，正好赶上开局。吕岱诛士徽后被废为庶人，后坐法诛。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("士䵋", "士䵋", "士䵋 Shi Wei / Sĩ Vĩ", "士燮次弟；徐闻令（徐闻属合浦郡） → 九真太守", "朱符死后由士燮表领九真太守，接替被杀的儋萌；事迹不多。", "能力取中等偏下的郡守水平。", null, null, "yes", "han", "m"),
            new WorldGeneralInfo("士武", "士武", "士武 Shi Wu / Sĩ Vũ", "士燮三弟；后领南海太守", "朱符死后领南海太守，归吴前（约210年前）已病卒。史书只记其官职。", "能力取偏武的郡守水平。", null, null, "yes", "han", "m"),
            new WorldGeneralInfo("儋萌", "儋萌", "儋萌 Dan Meng / Đam Manh", "九真太守（约190年前后在任）", "为岳父周京设宴时，功曹番歆强邀周京起舞，儋萌怒而杖杀番歆；番歆之弟番苗率众攻府，用毒箭射杀儋萌，士燮遣兵讨伐也没能攻克（《三国志·薛综传》）。性急少谋。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("士徽", "士徽", "士徽 Shi Hui / Sĩ Huy", "士燮第三子；后为安远将军、九真太守，226年自署交趾太守抗吴", "190年已二十五岁。226年士燮死后拒不受代，发宗兵守海口；被吕岱率军浮海奔袭，诈降后与兄弟士祗、士干、士颂一同被斩。勇而无谋。", "按经典剧本中君主成年子弟在任的惯例（如孙策、马超、刘璋）编入士燮势力。", 165, 227, "yes", "han", "m"),
            new WorldGeneralInfo("士匡", "士匡", "士匡 Shi Kuang / Sĩ Khuông", "士壹之子；中郎将，吕岱的师友从事", "吕岱让他写信、亲往劝士徽出降；事后被废为庶人。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("程秉", "程秉（字德枢）", "程秉 Cheng Bing", "汝南南顿人；士燮长史 → 吴太子太傅", "早年受业于郑玄，后避乱交州，与刘熙考论大义，博通五经；著有《周易摘》《尚书驳》《论语弼》。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("薛综", "薛综（字敬文）", "薛综 Xue Zong", "沛郡竹邑人；吴五官中郎将、合浦/交趾太守 → 太子少傅", "少时随族人避地交州、从刘熙学；220年随吕岱讨平交州、进攻九真，留下论交州治乱的名疏；文才冠于吴廷。", null, null, 243, "yes", "han", "m"),
            new WorldGeneralInfo("许靖", "许靖（字文休）", "许靖 Xu Jing", "汝南名士（与许劭主持“月旦评”）→ 避居交趾 → 蜀汉司徒", "约196年孙策取会稽时，与袁沛、邓子孝等浮海南至交州，士燮厚加敬待；211年前后入蜀。", "190年他还在中原，游戏中作为交趾的隐士。", null, 222, "yes", "han", "m"),
            new WorldGeneralInfo("袁徽", "袁徽", "袁徽 Yuan Hui", "陈国名士，寄寓交州", "写信给尚书令荀彧，称士燮“学问优博，又达于从政”，又称许靖“英才伟士，智略足以计事”，是品评人物的清流。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("番苗", "番苗", "番苗 Phan Miao / Phan Miêu", "九真郡吏、功曹番歆之弟；率众攻杀太守儋萌", "为兄复仇，以毒箭射杀儋萌，又顶住了士燮的讨伐军；本地豪强，武勇而少谋。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("李进", "李进（字子贤）", "李进 Li Jin / Lý Tiến", "交州本地人；中平三年（186）任交州（交趾）刺史", "上书说“今登仕朝廷，皆中州之士，未尝奖劝远人”，朝廷因此诏许交州孝廉、茂才补本州长吏。籍贯有“高兴（今化州，汉属合浦郡）”与“交趾”二说，离任后行迹不详。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("桓晔", "桓晔（字文林，一名严）", "桓晔 Huan Ye", "名儒桓荣后裔；避乱客居交趾", "据《后汉书·桓荣传》附传：字文林，一名严；初平中天下乱，避地会稽，又浮海客居交阯，“越人化其节，至闾里不争讼”，后为凶人所诬，死于合浦狱中。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("朱符", "朱符", "朱符 Zhu Fu / Chu Phù", "交趾刺史（灵帝末—献帝初）；太尉朱儁之子", "任用乡人分作长吏、横征暴敛，导致百姓怨叛、山贼攻州突郡，自己“走入海，流离丧亡”；还曾遣骑都尉刘彦为弟朱皓复仇。施政失败。", "政治极低。", null, null, "yes", "han", "m"),
            new WorldGeneralInfo("史璜", "史璜", "史璜 Shi Huang", "苍梧太守（任期起点不详，张津被杀前后卒于任上）", "《士燮传》：张津被杀时“苍梧太守史璜死，表又遣吴巨代之”，可见史璜在汉末长期任苍梧太守；他的卒年与张津之死同时，有203年与207/208年两说。190年是否已经到任不能确定，按中等郡守设值。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("刘彦", "刘彦", "刘彦 Liu Yan", "朱符的乡人、长吏；骑都尉", "《薛综传》说他与虞褒都侵虐百姓；《牟子理惑论》记载州牧（朱符）因其弟豫章太守被笮融杀害，“遣骑都尉刘彦将兵赴之”。武官，粗暴。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("虞褒", "虞褒", "虞褒 Yu Bao", "朱符的乡人、长吏", "与刘彦并称“侵虐百姓，强赋于民”的苛吏，史书只留下名字与恶评。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("张津", "张津（字子云）", "张津 Zhang Jin", "南阳人，大将军何进的亲信 → 交阯刺史、交州牧（约197年后至建安中）", "袁绍曾通过他劝何进尽诛宦官；到交州后好鬼神事，常著绛帕头、鼓琴烧香、读道书，连年发兵北攻刘表，军心离散，被部将区景所杀。卒年有203年、207年、208年诸说；《交广春秋》称建安六年（201）他仍为交州牧。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("区景", "区景", "区景 Ou Jing / Khu Cảnh", "张津部将 → 吴巨帐下都督", "《士燮传》：张津“为其将区景所杀”。后为苍梧太守吴巨的都督，“勇略与巨同”（《吴历》）；211年与吴巨同被步骘斩首示众（一说210年）。一说为长沙人。", null, null, 211, "yes", "han", "m"),
            new WorldGeneralInfo("吴巨", "吴巨（一作吴臣）", "吴巨 Wu Ju", "长沙人；刘表所遣苍梧太守，刘备旧识", "赶走同样由刘表派来的刺史赖恭；208年刘备曾想投奔他，鲁肃评他是“凡人，偏在远郡”。建安十五年（210）步骘出任交州刺史，次年（211）以会面为名将他与都督区景一并斩杀。", null, null, 211, "yes", "han", "m"),
            new WorldGeneralInfo("赖恭", "赖恭", "赖恭 Lai Gong", "零陵人；刘表所署交州刺史 → 蜀汉太常", "史称“先辈仁谨，不晓时事”，被吴巨逐走，后归刘备。为人仁厚，但缺乏应变之才。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("牟子", "牟子（相传名融，字子博）", "Mouzi", "苍梧学者；《牟子理惑论》作者", "序文自述：灵帝崩后“独交州差安”，牟子奉母避世交趾，二十六岁回苍梧娶妻；州牧（朱符）、太守多次征辟都推辞不就。兼通儒道佛，是中国最早的护法论作者之一（成书年代有争议）。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("刘熙", "刘熙（字成国）", "刘熙 Liu Xi", "北海名儒，避地交州的“征士”", "往来苍梧、南海，客授生徒数百人，著《释名》二十七篇以及《谥法》《孟子注》；程秉、薛综、许慈都出自他门下；约卒于建安末。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("许慈", "许慈（字仁笃）", "许慈 Xu Ci", "南阳人；刘熙弟子 → 蜀汉博士、大长秋", "精通郑玄之学，治《易》《尚书》《三礼》《毛诗》《论语》；建安中与许靖一同由交州入蜀。", null, null, null, "yes", "han", "m"),
            new WorldGeneralInfo("步骘", "步骘（字子山）", "步骘 Bu Zhi", "临淮淮阴人；210年孙权所遣交州刺史 → 吴丞相", "以会面为名斩杀吴巨，威声大震，士燮兄弟相率归附；217年把州治移到番禺。190年他还是避乱江东的少年，作为在野人才放在番禺。", null, null, 247, "yes", "han", "m"),
            new WorldGeneralInfo("吕岱", "吕岱（字定公）", "吕岱 Lü Dai", "广陵海陵人；220年起任交州刺史，平定士徽 → 吴大司马", "226年浮海奔袭交趾诛灭士氏，又讨平九真，派从事向南宣扬国威，扶南、林邑、堂明诸王都遣使奉贡；九十六岁才去世。文武兼备。", null, 161, 256, "yes", "han", "m"),
            new WorldGeneralInfo("区连", "区连（《水经注》引《林邑记》作区逵）", "Khu Liên / Ou Lian", "日南郡象林县功曹之子 → 林邑开国之王", "“杀令，自号为王，子孙相承”，开创了延续千余年的占婆政权；能聚众破县、据地自立。", "武力偏高、政略中等。", null, null, "yes", "seasia", "m"),
            new WorldGeneralInfo("混盘况", "混盘况", "Hun Panhuang (Hỗn Bàn Huống)", "扶南王（2世纪后期在位），混填后裔", "“以诈力间诸邑，令相疑阻，因举兵攻并之”，再派子孙分治诸邑、号为小王。190年已年老（九十余岁才死，约3世纪初）。", "年老多诈，武力低、智谋高。", null, null, "yes", "seasia", "m"),
            new WorldGeneralInfo("盘盘", "混盘盘", "Hun Panpan (Bàn Bàn)", "混盘况中子；继位三年而死", "即位后把国事全部委托给大将范蔓，是混氏王朝的末代君主（并非5世纪马来半岛的盘盘国）。", null, null, null, "yes", "seasia", "m"),
            new WorldGeneralInfo("范师蔓", "范蔓（《梁书》）/ 范师蔓（《南齐书》）", "Fan Shiman (Phạm Sư Man)", "扶南大将 → 扶南大王（约205—225）", "“勇健有权略”，被国人推举为王；造大船横渡涨海，攻屈都昆、九稚、典孙等十余国，开地五六千里，自号扶南大王；准备讨伐金邻时病死。东南亚的头号名将。《南齐书·扶南传》作“至王槃况死，国人立其大将范师蔓”，略去了盘盘。", null, null, 225, "yes", "seasia", "m"),
            new WorldGeneralInfo("范金生", "范金生", "Fan Jinsheng (Phạm Kim Sinh)", "范师蔓的太子", "父亲病重时代父领兵讨伐金邻，被表兄范旃派人诈骗后杀害。生年不详（应在205年前后或更早），按隐士收录。", null, null, 225, "yes", "seasia", "m"),
            new WorldGeneralInfo("范旃", "范旃", "Fan Zhan (Phạm Chiên)", "范师蔓姊子、二千人将 → 篡立为扶南王（约225/230—243年后）", "用诈术杀死太子金生后自立；派亲人苏物出使天竺，243年遣使向孙吴进献乐人与方物；其后被范师蔓幼子范长袭杀（卒年不详，约243—245年；一说在位230—243年或更迟）。", null, null, 244, "yes", "seasia", "m"),
            new WorldGeneralInfo("苏物", "苏物", "Su Wu", "范旃的亲人；出使天竺的扶南使者", "《梁书·中天竺传》：从扶南出发，取道拘利口，沿海湾西北航行一年多抵达天竺江口，再逆水七千里到达；天竺王回派陈、宋二人携月支马四匹报聘，前后历时四年才回国。", null, null, null, "yes", "seasia", "m"),
            new WorldGeneralInfo("胡维色迦", "胡维色迦（胡毗色伽）", "Huvishka", "贵霜皇帝（大王、王中之王、天子）", "迦腻色伽之后的贵霜皇帝，铭文纪年为迦腻色伽纪元28—60年（约155—187年），在巴尔赫到秣菟罗之间铸币，钱币神祇之多为历代之冠；秣菟罗出土的阿弥陀佛造像刻于其在位第28年。以守成、整合著称。卒年约190年。", "政治高于武力。", null, 190, "yes", "kushan", "m"),
            new WorldGeneralInfo("波调", "韦苏提婆一世（波调）", "Vasudeva I", "贵霜王储，后为贵霜皇帝（约191—232年）", "铭文纪年64/67—98年（约191—232年），几乎全部出自秣菟罗，重心在印度；是第一位以印度神名为名的贵霜王。《三国志·明帝纪》太和三年（229年）“大月氏王波调遣使奉献，以调为亲魏大月氏王”。与胡维色迦的亲属关系不详。", "游戏中作为镇守秣菟罗的继承人。", null, null, "yes", "kushan", "m"),
            new WorldGeneralInfo("迦腻色伽", "迦腻色伽二世", "Kanishka II", "贵霜皇帝（约232—247年）", "波调的继承者，钱币显示其仍维持北印度统治，巴克特里亚大概在他在位时落入萨珊之手。生年不详（以约232年即位推算应生于205年前），190年时尚年幼或未出生，作为在野人才放在塔克西拉。与贵霜盛世的迦腻色伽一世（约127—150年在位）同名，全名作迦腻色伽二世以示区别。", null, null, null, "yes", "kushan", "m"),
            new WorldGeneralInfo("鲁德拉辛哈", "鲁德拉辛哈一世", "Rudrasimha I", "西部总督王朝大总督（Mahakshatrapa）", "鲁德拉达曼一世之子；纪年钱币显示约178—197年间先后以总督、大总督身份统治，约188—190年间只称总督（旧说认为大总督之位一度被阿毗罗人伊湿伐罗达多夺去）。", null, null, 197, "yes", "kushan", "m"),
            new WorldGeneralInfo("吉瓦达曼", "吉瓦达曼", "Jivadaman", "西部总督王族（前大总督）", "达摩阇陀室利一世之子、鲁德拉辛哈之侄，约178—181年和197—199年两度称大总督，其间由叔父掌权。", "大权旁落于叔父，开局忠诚偏低；驻地为游戏安排。", null, 199, "yes", "kushan", "m"),
            new WorldGeneralInfo("鲁德拉塞纳", "鲁德拉塞纳一世", "Rudrasena I", "西部总督王朝大总督（约200—222年）", "鲁德拉辛哈一世之子，约199年称总督，200—222年为大总督，继承无子的堂兄吉瓦达曼，在位二十余年。生年不详，190年应已成年。", "作为王子在任，随父鲁德拉辛哈驻乌贾因（约199年才称总督）。", null, 222, "yes", "kushan", "m"),
            new WorldGeneralInfo("沃洛吉斯", "沃洛吉斯四世", "Vologases IV (Walagash)", "安息王中之王（147—191年）", "米特里达梯五世之子。151年击败卡拉塞尼王收复两河口；161年进攻罗马，其军在埃勒格亚歼灭卡帕多细亚总督塞维里亚努斯的军团并侵入叙利亚，但165年塞琉西亚、泰西封被阿维狄乌斯·卡西乌斯攻破。在位四十余年，191年卒。", null, null, 191, "yes", "persia", "m"),
            new WorldGeneralInfo("奥斯罗埃斯", "奥斯罗埃斯二世", "Osroes II", "安息王位争夺者（约190年）", "只见于钱币的安息争位者，约190年在伊朗高原铸币，与沃洛吉斯四世、五世对立；控制范围不详。", "暂放在铸币中心埃克巴坦那，忠诚60以表现割据。", null, null, "yes", "persia", "m"),
            new WorldGeneralInfo("瓦加尔什", "沃洛吉斯五世（亚美尼亚王瓦加尔什二世）", "Vologases V / Vagharsh II of Armenia", "安息王子、亚美尼亚王（约180—191年），后为安息王（191—208年）", "沃洛吉斯四世之子，先任亚美尼亚王，191年回国继位为沃洛吉斯五世；193年答应援助罗马僭位者尼格尔，197—198年塞维鲁沿幼发拉底河南下攻陷泰西封、大肆掳掠。", "用亚美尼亚名以免与其父同名。开局放在泰西封（191年回国继位），亚美尼亚由其子霍斯罗夫镇守。", null, 208, "yes", "persia", "m"),
            new WorldGeneralInfo("霍斯罗夫", "霍斯罗夫一世", "Khosrov I of Armenia", "亚美尼亚王子，后为亚美尼亚王（191—217年）", "瓦加尔什之子，191年继为亚美尼亚王；约214—216年被卡拉卡拉诱捕，亚美尼亚人随即起兵，击败罗马将领狄奥克利图斯。", null, null, 217, "yes", "persia", "m"),
            new WorldGeneralInfo("戈契赫尔", "戈契赫尔", "Gochihr (Gōzihr)", "波西斯王（巴兹兰吉家族，安息藩王）", "据塔巴里，巴兹兰吉王戈契赫尔居白城，帕佩克曾请他把七岁的阿尔达希尔送到达拉布格尔德的提里处；约205/206年被帕佩克推翻。在位起讫不详。", "波西斯拆为独立势力，以他为君主。", null, null, "yes", "persia", "m"),
            new WorldGeneralInfo("帕佩克", "帕佩克（巴巴克）", "Pāpak (Bābak)", "克尔领主、伊斯塔克尔阿娜希塔火庙守护者", "萨珊之子，萨珊王朝之父；约205/206年推翻戈契赫尔、夺取伊斯塔克尔，请求安息王承认其子沙普尔为王而不得，约207—210年间卒。", "随戈契赫尔归入独立的波西斯势力。卒年取208年；忠诚偏低以体现其野心。", null, 208, "yes", "persia", "m"),
            new WorldGeneralInfo("提里", "提里", "Tīrē", "达拉布格尔德城堡长官（argbed），宦官", "据塔巴里，提里是巴兹兰吉王戈契赫尔手下的宦官，任达拉布格尔德城堡长官；阿尔达希尔约七岁时被送到他那里抚养，提里死后阿尔达希尔继任其职。", "随戈契赫尔归入独立的波西斯势力。能力按地方守将设定。", null, null, "yes", "persia", "m"),
            new WorldGeneralInfo("巴拉什", "沃洛吉斯六世（巴拉什）", "Vologases VI (Walagash/Balāsh)", "安息王（208—约228年）", "沃洛吉斯五世之子，208年继位，213年起与弟阿尔达班四世争国，退守美索不达米亚，以塞琉西亚铸币至约228年。", "用中古波斯语形式“巴拉什”以免与祖父同名。", null, 228, "yes", "persia", "m"),
            new WorldGeneralInfo("阿尔达班", "阿尔达班四世", "Artabanus IV (Ardawān)", "安息末代王中之王（约213—224年）", "沃洛吉斯五世之子，213年起据米底与兄争国；217年在尼西比斯击败罗马皇帝马克里努斯，迫其赔款求和；224年在霍尔木兹甘之战中被阿尔达希尔所杀，安息亡。", null, null, 224, "yes", "persia", "m"),
            new WorldGeneralInfo("霍瓦萨克", "霍瓦萨克", "Khwasak", "苏萨总督（215年）", "215年苏萨石碑上从阿尔达班四世手中接受权力象征的苏萨总督，是安息末年可考的地方大员。", null, null, null, "yes", "persia", "m"),
            new WorldGeneralInfo("梯里达底", "梯里达底二世", "Tiridates II of Armenia", "亚美尼亚王（217—252年）", "霍斯罗夫一世之子，217年在罗马支持下即位，长期抗拒萨珊；与“霍斯罗夫二世”的关系在亚美尼亚史料中有混淆。生年不详。", null, null, 252, "yes", "persia", "m"),
            new WorldGeneralInfo("阿尔达希尔", "阿尔达希尔一世", "Ardashir I (Ardaxšīr)", "萨珊王朝开国君主（224—242年）", "帕佩克之子，约180年生，幼年在达拉布格尔德由提里抚养并继任长官；夺取波西斯后连败诸藩王，224年在霍尔木兹甘击杀阿尔达班四世，约226年在泰西封称“伊朗诸王之王”，又攻罗马美索不达米亚，开创萨珊王朝。", null, 180, 242, "yes", "persia", "m"),
            new WorldGeneralInfo("沙普尔", "沙普尔（帕佩克之子）", "Shapur (son of Papak)", "波西斯王（约208—211年）", "帕佩克长子，父死后继为波西斯王，与弟阿尔达希尔不和；约211年在进军途中意外身亡，王位归阿尔达希尔。与后来的沙普尔一世不是同一人。", null, null, 211, "yes", "persia", "m"),
            new WorldGeneralInfo("萨珊", "萨珊", "Sāsān", "伊斯塔克尔阿娜希塔火庙守护者", "萨珊王朝得名的始祖，据塔巴里为火庙守护者、娶巴兹兰吉家族女子；沙普尔一世的卡巴扎尔达什特铭文提到“萨珊君主”。是否活到190年不详，作为火庙中的隐者。", null, null, null, "yes", "persia", "m"),
            new WorldGeneralInfo("阿布萨米亚", "阿布萨米亚（又译阿卜德萨米亚，拉丁名巴尔塞米乌斯）", "ʿAbdsamiya (Barsemius)", "哈特拉王（阿拉伯人之王）", "萨纳特鲁克一世（约140—180年）之子，约180—205年在位，故190年的哈特拉王是他；赫罗狄安记载193年“哈特拉王巴尔塞米乌斯”援助尼格尔，一般认为就是他；塞维鲁第二次东征时（约197—199年间）两次围攻哈特拉都未能攻下。", null, null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("萨纳特鲁克", "萨纳特鲁克二世", "Sanatruq II", "哈特拉王（约205—240/241年）", "阿卜德萨米亚之子，约205年继位，有九件铭文，称“阿拉伯人之王”；在位期间哈特拉转为罗马藩属，235年已有罗马驻军；240/241年哈特拉被沙普尔一世攻陷。生年不详，但在位到241年，190年当尚年幼，故作为在野人才（原设为在任王子）。", null, null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("阿布加尔", "阿布加尔八世（大王）", "Abgar VIII the Great", "奥斯若恩王（177—212年）", "马努八世之子；194/195年与阿迪亚贝纳人围攻尼西比斯，塞维鲁征讨后在奥斯若恩设行省，但保留他在埃德萨的王位，后来他访问罗马受到隆重接待；201年洪水后重建埃德萨。基督教传统称他是最早改宗的君主之一（有争议）。", null, null, 212, "yes", "arab", "m"),
            new WorldGeneralInfo("巴戴桑", "巴尔·戴桑（巴戴桑）", "Bardaisan (Bar Dayṣān)", "埃德萨宫廷哲学家、诗人、占星家", "154年生于埃德萨，222年卒；阿布加尔八世的友人与廷臣，叙利亚语诗歌与哲学的开创者（弟子记其学说为《诸国律书》）；朱利乌斯·阿非利加努斯记其在阿布加尔宫中以箭在盾上射出人形。", "善射，武力不低。", 154, 222, "yes", "arab", "m"),
            new WorldGeneralInfo("哈莫尼乌斯", "哈莫尼乌斯", "Harmonius", "巴戴桑之子，叙利亚语赞美诗作者", "据索佐门、狄奥多勒记载，以叙利亚语韵律作赞美诗传播其父学说，百余年后叙利亚的厄弗冷仿其韵律另作赞美诗与之抗衡。生年不详，作为在野人才。", null, null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("列夫", "列夫一世（公正者）", "Rev I the Just", "伊比利亚王（189—216年）", "据格鲁吉亚编年史，为亚美尼亚王沃洛吉斯（瓦加尔什）之子、阿马扎斯普二世的外甥，189年阿马扎斯普二世被推翻后即位，号“公正者”，禁止以儿童献祭。仅见于中世纪编年史，图曼诺夫视为史实。", null, null, 216, "yes", "persia", "m"),
            new WorldGeneralInfo("瓦切", "瓦切一世", "Vache I of Iberia", "伊比利亚王（216—234年）", "列夫一世之子，216—234年在位，同样仅见于格鲁吉亚编年史。生年不详，作为在野人才。", null, null, 234, "yes", "persia", "m"),
            new WorldGeneralInfo("阿勒汗", "阿勒汗·纳赫凡", "ʿAlhān Nahfān", "萨巴与祖赖丹王", "雅里姆·艾曼之子；萨巴王，与其子沙伊鲁姆·奥塔尔、雅里姆·艾曼共治（CIH 308，约200年）；里亚姆山十余件铭文记其与“阿比西尼亚人之王”加达拉特订立盟约。在位年代一般作约200年前后（一说约195—210年，一说卒于约220年）。", "190年是否已即位不能确定，放宽年代采用。", null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("沙伊鲁姆", "沙伊鲁姆·奥塔尔", "Shaʿirum Awtar", "萨巴王子（共治者），后为萨巴与祖赖丹王", "阿勒汗之子，约200年已与父共治，约210年（一说约220年）独掌萨巴；先介入哈德拉毛平定反对其妹夫伊勒阿兹·雅卢特的叛乱，约225年又攻入哈德拉毛、俘伊勒阿兹、占沙布瓦；又北伐卡里亚特法奥的金达人，并与阿比西尼亚军交战，是萨巴最后的强王之一。", null, null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("塔兰", "塔兰·亚乌布·尤汉阿姆", "Thaʾrān Yaʿūb Yuhanʿim", "希木叶尔王（萨巴与祖赖丹王，约175—214年独治）", "达马尔阿里·尤哈比尔之子，约155年起与父共治，约175年继位，独治到约214年。父子二人的真人大小青铜像（希腊工匠福卡斯参与铸造）出土于扎玛尔省的纳赫拉·哈姆拉，今藏萨那国立博物馆。另有学者把父子年代推后到约180—220年，误差较大。", null, null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("伊勒阿兹", "伊勒阿兹·雅卢特", "Ilʿazz Yalut", "哈德拉毛王（约3世纪初，约225年被萨巴所俘）", "乌格拉山（沙布瓦附近）的铭文记其举行王室典礼与狩猎时有帕尔米拉、迦勒底与印度使节各两人在场；娶萨巴王沙伊鲁姆·奥塔尔之妹，沙伊鲁姆先曾助他平叛，约225年又因他入侵卡塔班而攻入哈德拉毛、将他俘虏并占领沙布瓦。", "190年前后的哈德拉毛王名不详，放宽年代采用他。", null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("加达拉特", "加达拉特（GDRT）", "GDRT (Gadarat)", "阿克苏姆王（阿比西尼亚人之王，约200年）", "萨巴铭文称他为“阿比西尼亚人之王”，先与萨巴王阿勒汗结盟，后又插手也门诸国之争；提格雷出土的青铜器铭有“阿克苏姆王 GDR”。是可考最早的阿克苏姆王之一。", null, null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("贝加特", "贝加特（BYGT）", "BYGT (Beygat)", "阿克苏姆王子（“奈加什之子”）", "萨巴铭文（Ja 631）记“奈加什之子贝加特”与阿比西尼亚军进逼希木叶尔都城扎法尔，时在沙伊鲁姆·奥塔尔与阿克苏姆关系破裂之际；一般认为是加达拉特之子。生年不详，作为在野人才。", null, null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("康茂德", "卢基乌斯·奥勒留·康茂德", "Lucius Aurelius Commodus", "皇帝（奥古斯都，180—192年在位）", "体格强健、以亲自下场角斗与射杀猛兽自诩；荒于政事、任用宠臣；192年末遇刺。", "武力偏高，智力、政治极低。", 161, 192, "yes", "roman", "m"),
            new WorldGeneralInfo("克里安德", "马可·奥勒留·克里安德", "Marcus Aurelius Cleander", "宫廷侍从长、禁卫军长官（被释奴）", "佩伦尼斯死后独揽大权，大肆卖官（一年出现二十五位执政官）；190年粮荒暴动中被康茂德交给民众处死——剧本开局时仍在位。", null, null, 190, "yes", "roman", "m"),
            new WorldGeneralInfo("佩蒂纳克斯", "普布利乌斯·赫尔维乌斯·佩蒂纳克斯", "Publius Helvius Pertinax", "罗马城市长官（189年起）", "被释奴之子出身，马科曼尼战争名将，历任默西亚、达契亚、叙利亚、不列颠总督（185年平定兵变）、188—189年阿非利加总督；193年继位后整顿财政，87天后被禁卫军所杀。", null, 126, 193, "yes", "roman", "m"),
            new WorldGeneralInfo("莱图斯", "昆图斯·埃米利乌斯·莱图斯", "Quintus Aemilius Laetus", "禁卫军长官（190/191—193年）", "阿非利加人，克里安德倒台后掌禁卫军，举荐阿非利加同乡塞维鲁出镇上潘诺尼亚；主谋刺杀康茂德并拥立佩蒂纳克斯，193年被尤利安努斯处死。", "忠诚偏低（192年参与弑君）。", null, 193, "yes", "roman", "m"),
            new WorldGeneralInfo("埃克莱图斯", "埃克莱克图斯", "Eclectus", "宫廷侍从长（被释奴）", "先后侍奉维鲁斯与康茂德，与玛琪亚、莱图斯合谋弑君；193年禁卫军哗变时唯一留在佩蒂纳克斯身边抵抗而死。", "忠诚偏低（192年参与弑君），宫廷近侍不领兵。", null, 193, "yes", "roman", "m"),
            new WorldGeneralInfo("玛琪亚", "玛琪亚·奥雷利亚·凯奥尼娅·德米特里亚斯", "Marcia Aurelia Ceionia Demetrias", "康茂德的情妇", "182年起为康茂德宠姬，曾为撒丁岛矿场的基督徒求得赦免；发现自己在处死名单上后下毒弑君，193年被尤利安努斯处死。", "忠诚偏低（192年参与弑君），不领兵。", null, 193, "yes", "roman", "f"),
            new WorldGeneralInfo("塞维鲁", "卢基乌斯·塞普蒂米乌斯·塞维鲁", "Lucius Septimius Severus", "上潘诺尼亚总督（191—193年；190年为执政官）", "大莱普提斯人，186—189年卢格杜努姆总督，189年西西里总督，190年执政官，191年出镇上潘诺尼亚；193年起兵，先后击败尤利安努斯、尼格尔、阿尔拜努斯并东征安息，开创塞维鲁王朝。放在卡农图姆以体现其起兵根据地。", null, 145, 211, "yes", "roman", "m"),
            new WorldGeneralInfo("多姆娜", "尤利娅·多姆娜", "Julia Domna", "塞维鲁之妻", "叙利亚埃梅萨祭司王族之女，187年嫁塞维鲁；后为皇后，聚集哲学家与文人，卡拉卡拉在位时代理大量政务。生年约160（一说170）。", null, 160, 217, "yes", "roman", "f"),
            new WorldGeneralInfo("尤·莱图斯", "尤利乌斯·莱图斯", "Julius Laetus", "塞维鲁麾下将领（骑兵统帅）", "193年起随塞维鲁作战；197年卢格杜努姆会战率骑兵杀出定胜负，同年死守尼西比斯；因深得军心遭忌，约198年被塞维鲁处死。190年职务不详，按其后来的从属放在潘诺尼亚。", null, null, 198, "yes", "roman", "m"),
            new WorldGeneralInfo("尼格尔", "盖乌斯·佩斯切尼乌斯·尼格尔", "Gaius Pescennius Niger", "叙利亚总督（190/191—193年）", "意大利骑士家族出身，183年在达契亚击败萨尔马提亚人与自由达契亚人而成名，素有清名、深得罗马民众拥护；193年在安条克称帝，194年伊苏斯战败被杀。亦译“奈哲尔”。", null, 135, 194, "yes", "roman", "m"),
            new WorldGeneralInfo("阿塞利乌斯", "阿塞利乌斯·埃米利亚努斯", "Asellius Aemilianus", "叙利亚总督（187—190年），后任亚细亚资深执政官", "历任多省的资深元老；193年为尼格尔镇守拜占庭与马尔马拉海南岸，在基齐库斯被坎迪杜斯击败、被俘处死。", null, null, 193, "yes", "roman", "m"),
            new WorldGeneralInfo("阿尔拜努斯", "德基姆斯·克劳狄乌斯·阿尔拜努斯", "Decimus Clodius Albinus", "不列颠总督（191/192—197年）", "阿非利加哈德鲁梅图姆人，182—183年在达契亚立功，约185年执政官，189年前后任下日耳曼总督；193年受塞维鲁“凯撒”名号，195年称帝，197年卢格杜努姆败死。亦译“阿尔比努斯”。", null, 150, 197, "yes", "roman", "m"),
            new WorldGeneralInfo("尤利安努斯", "马库斯·狄狄乌斯·尤利安努斯", "Marcus Didius Severus Julianus", "阿非利加资深执政官（189—190年）", "由马可·奥勒留之母抚养，任比利时高卢总督时击退考契人，历任达尔马提亚、下日耳曼、比提尼亚总督；189年接替佩蒂纳克斯治阿非利加；193年在禁卫军“拍卖”中出价买得帝位，66天后被杀。", null, 133, 193, "yes", "roman", "m"),
            new WorldGeneralInfo("阿努利努斯", "普布利乌斯·科尔内利乌斯·阿努利努斯", "Publius Cornelius Anullinus", "资深元老、塞维鲁的老上司", "西班牙伊利贝里斯人，约170年任贝提卡总督时塞维鲁是其财务官，约175年执政官、上日耳曼总督，192/193年阿非利加总督；194年伊苏斯会战大败尼格尔，199年再任执政官。190年职务不详，放在卢格杜努姆只为高卢配守将。", null, null, null, "yes", "roman", "m"),
            new WorldGeneralInfo("坎迪杜斯", "提比略·克劳狄乌斯·坎迪杜斯", "Tiberius Claudius Candidus", "尼科米底亚与以弗所城市监理", "骑士出身的军需官，康茂德时破格擢入元老院，在亚细亚任职并监理尼科米底亚、以弗所；193年为塞维鲁先锋，在基齐库斯、尼西亚两败尼格尔军，后任近西班牙总督。", null, null, null, "yes", "roman", "m"),
            new WorldGeneralInfo("卢普斯", "维里乌斯·卢普斯", "Virius Lupus", "下日耳曼总督（约196年在任）", "196年率莱茵军团阻击阿尔拜努斯失利；197年起任不列颠总督，向迈阿泰人重金买和并修复北方要塞。190年职务不详（下日耳曼当时总督资料极少），提前放在科洛尼亚。", null, null, null, "yes", "roman", "m"),
            new WorldGeneralInfo("普登斯", "盖乌斯·瓦勒里乌斯·普登斯", "Gaius Valerius Pudens", "下潘诺尼亚总督（192—193年）", "193年随塞维鲁起兵；之后历任下日耳曼、不列颠（约202—205年，修建要塞）与阿非利加总督（211/212年），生平几乎全靠铭文。", null, null, null, "yes", "roman", "m"),
            new WorldGeneralInfo("马克西穆斯", "卢基乌斯·马略·马克西穆斯", "Lucius Marius Maximus Perpetuus Aurelianus", "下默西亚第一意大利军团长（193年）", "193年率默西亚军围攻拜占庭，197年任默西亚与卢格杜努姆方面军统帅，后任比利时高卢、叙利亚总督，217年罗马城市长官；又是续写苏埃托尼乌斯的皇帝传记作家。", null, 160, 230, "yes", "roman", "m"),
            new WorldGeneralInfo("奇洛", "卢基乌斯·法比乌斯·奇洛", "Lucius Fabius Cilo", "加拉太总督（约189—192年）", "曾任第十六弗拉维亚军团长、纳博高卢总督与军库长官；193年率军守佩林图斯，后任本都—比提尼亚、上默西亚、上潘诺尼亚总督与罗马城市长官，是塞维鲁的心腹。", null, 153, null, "yes", "roman", "m"),
            new WorldGeneralInfo("卡斯图斯", "卢基乌斯·阿尔托留斯·卡斯图斯", "Lucius Artorius Castus", "第六胜利军团长官（年代不确定）", "只见于达尔马提亚波德斯特拉纳的墓志铭：曾任驻埃博拉库姆的第六胜利军团长官，并率不列颠军团与骑兵讨伐阿莫里卡人。克罗地亚学者坎比定为2世纪下半叶，但也有3世纪初之说；常被附会为亚瑟王原型。", null, null, null, "yes", "roman", "m"),
            new WorldGeneralInfo("提尼乌斯", "昆图斯·提尼乌斯·德米特里乌斯", "Quintus Tineius Demetrius", "埃及长官（189年8月—190年8月在任）", "骑士出身的埃及长官，纸草文书证实其在任时间；190年由克劳狄乌斯·卢基利亚努斯接替。事迹不多，按行政官评定。", null, null, null, "yes", "roman", "m"),
            new WorldGeneralInfo("鲁弗斯", "卢基乌斯·诺维乌斯·鲁弗斯", "Lucius Novius Rufus", "近西班牙（塔拉科）总督（约192—197年）", "197年率第七双子军团投奔阿尔拜努斯，战败后被塞维鲁处死。190年在任是提前两年的安排。", null, null, 197, "yes", "roman", "m"),
            new WorldGeneralInfo("奥盖卢", "奥盖卢·巴尔·马凯", "Ogeilu son of Maqqai", "帕尔米拉将军（商队护卫）", "199年帕尔米拉议会与四部落为他立像，表彰他多次出任将军、征讨游牧民并自掏腰包保护商队。190年已在任的可能性大但无直接证据。", "中文无通行译名，此为音译。", null, null, "yes", "arab", "m"),
            new WorldGeneralInfo("卡拉卡拉", "马可·奥勒留·安东尼努斯（卡拉卡拉）", "Caracalla (Lucius Septimius Bassianus)", "塞维鲁长子（190年两岁）", "188年4月生于卢格杜努姆；211年杀弟独掌帝国，212年颁布敕令授予全体自由民罗马公民权；好武、残暴，217年遇刺。", null, 188, 217, "yes", "roman", "m"),
            new WorldGeneralInfo("盖塔", "普布利乌斯·塞普蒂米乌斯·盖塔", "Publius Septimius Geta", "塞维鲁次子（190年一岁）", "189年3月生于罗马；211年与兄长共治，同年被卡拉卡拉杀害于母亲怀中。", null, 189, 211, "yes", "roman", "m"),
            new WorldGeneralInfo("马克里努斯", "马库斯·奥佩利乌斯·马克里努斯", "Marcus Opellius Macrinus", "律师（日后禁卫军长官、皇帝）", "毛里塔尼亚凯撒利亚人，以律师与财务管理起家，212年任禁卫军长官，217年谋杀卡拉卡拉后称帝，次年败给埃拉伽巴路斯。", null, 165, 218, "yes", "roman", "m"),
            new WorldGeneralInfo("普劳提安", "盖乌斯·富尔维乌斯·普劳提亚努斯", "Gaius Fulvius Plautianus", "塞维鲁的同乡与亲戚", "大莱普提斯人，197—205年任禁卫军长官、权倾一时，女儿嫁卡拉卡拉；205年被指控谋反处死。百度百科作“普罗汀纳斯”。", null, 150, 205, "yes", "roman", "m"),
            new WorldGeneralInfo("盖伦", "克劳狄乌斯·盖伦", "Aelius (Claudius) Galenus", "宫廷御医、医学家", "帕加马人，先后为马可·奥勒留、康茂德、塞维鲁诊病，其解剖学与医学著作统治西方医学一千多年；与华佗同为“神医”类人才。卒年旧说199/200，今多取约216年。", null, 129, 216, "yes", "roman", "m"),
            new WorldGeneralInfo("帕比尼安", "埃米利乌斯·帕比尼安", "Aemilius Papinianus", "法学家（日后禁卫军长官）", "罗马五大法学家之首，可能出身叙利亚；203—212年任禁卫军长官，因拒绝为卡拉卡拉弑弟辩护被处死。亦译“帕皮尼亚努斯”。", "按张昭一类的内政之才定能力。", 142, 212, "yes", "roman", "m"),
            new WorldGeneralInfo("乌尔比安", "多米提乌斯·乌尔比安", "Gnaeus Domitius Annius Ulpianus", "法学家（日后禁卫军长官）", "腓尼基推罗人，帕比尼安的助手，222年起任亚历山大·塞维鲁的禁卫军长官，223年（一说228年）被禁卫军所杀；其著作占《学说汇纂》约三分之一。", null, 170, 223, "yes", "roman", "m"),
            new WorldGeneralInfo("狄奥", "卢基乌斯·卡西乌斯·狄奥", "Lucius Cassius Dio", "元老、史学家", "比提尼亚尼西亚人，康茂德时入元老院，194/195年任大法官，后任阿非利加、达尔马提亚、上潘诺尼亚总督，229年与亚历山大·塞维鲁同任执政官；所著《罗马史》是这一时期罗马史最主要的史源。", null, 155, 235, "yes", "roman", "m"),
            new WorldGeneralInfo("马克西明", "盖乌斯·尤利乌斯·维鲁斯·马克西米努斯（色雷克斯）", "Maximinus Thrax", "色雷斯农家子（日后皇帝）", "身材魁梧，在塞维鲁为盖塔庆生举办的竞技中连胜十六人而入伍；235年被拥立为第一位“军人皇帝”，238年被部下所杀。", null, 173, 238, "yes", "roman", "m"),
            new WorldGeneralInfo("戈尔迪安", "马库斯·安东尼乌斯·戈尔迪安努斯（戈尔迪安一世）", "Gordian I", "富有元老（日后皇帝）", "216年任下不列颠总督，237年任阿非利加资深执政官，238年在提斯德鲁斯被拥立为帝，在位仅二十余日。", null, 159, 238, "yes", "roman", "m"),
            new WorldGeneralInfo("德西乌斯", "盖乌斯·墨西乌斯·昆图斯·德西乌斯", "Decius", "潘诺尼亚人（日后皇帝）", "约201年生于西尔米乌姆附近的布达利亚；249年称帝，251年在阿伯里图斯败给哥特王尼瓦战死，是第一位死于外敌之手的罗马皇帝。", null, 201, 251, "yes", "roman", "m"),
            new WorldGeneralInfo("菲利普", "马库斯·尤利乌斯·菲利普斯（阿拉伯人菲利普）", "Philip the Arab", "阿拉伯行省人（日后皇帝）", "约204年生于特拉可尼的沙赫巴；244—249年在位，248年主持罗马建城千年庆典。放在最近的叙利亚城市帕尔米拉。", null, 204, 249, "yes", "arab", "m"),
            new WorldGeneralInfo("瓦勒良", "普布利乌斯·李锡尼乌斯·瓦勒良", "Valerian", "元老世家（日后皇帝）", "约199年生；253—260年在位，260年埃德萨之战被萨珊沙普尔一世俘虏，死于囚中（约264年后）。", null, 199, null, "yes", "roman", "m"),
            new WorldGeneralInfo("玛伊莎", "尤利娅·玛伊莎", "Julia Maesa", "多姆娜之姊", "埃梅萨祭司王族，218年以重金收买军队，扶立外孙埃拉伽巴路斯推翻马克里努斯，222年又改立亚历山大·塞维鲁；生年在约160年之前。", null, 160, 224, "yes", "roman", "f"),
            new WorldGeneralInfo("庞培亚努斯", "提比略·克劳狄乌斯·庞培亚努斯", "Tiberius Claudius Pompeianus", "马可·奥勒留之婿、退隐老将", "马科曼尼战争中马可最倚重的将领；182年其妻路基拉谋刺康茂德失败后，以年老为由退隐意大利庄园。193年回元老院，两度拒绝佩蒂纳克斯等人让给他的帝位。按退隐状态作为在野。此后不见于史，卒年不详（193年后）。", null, 125, null, "yes", "roman", "m"),
            new WorldGeneralInfo("纳尔奇苏斯", "纳尔奇苏斯", "Narcissus", "摔跤手、康茂德的陪练", "192年12月31日奉玛琪亚、莱图斯之命在浴室中勒死康茂德；193年被塞维鲁处死。", null, null, 193, "yes", "roman", "m"),
            new WorldGeneralInfo("阿根托科克斯", "阿根托科克苏斯", "Argentocoxos", "喀里多尼亚首领（约208—210年）", "狄奥记其210年议和后，其妻与尤利娅·多姆娜就两地风俗互相讥讽。名意为“银腿”。", "190年前后无可考首领，放宽年代收录。中文无通行译名，此为音译（按拉丁人名惯例省去词尾 -us）。", null, null, "yes", "celt", "m"),
            new WorldGeneralInfo("巴洛马尔", "巴洛马尔", "Ballomar", "马科曼尼王（见于166—约172年）", "166/167年代表十一族与罗马议和，随后领导联军翻越阿尔卑斯、围攻阿奎莱亚，是自辛布里人以来首支攻入意大利的外敌。卒年史无明文（一般推测在170—180年间）。", null, null, null, "yes", "german", "m"),
            new WorldGeneralInfo("富尔提乌斯", "富尔提乌斯", "Furtius", "夸迪王（约172年）", "与马可·奥勒留订约的亲罗马夸迪王，后被族人废黜、改立阿里奥盖苏斯；190年下落不详。", "放宽年代收录。", null, null, "yes", "german", "m"),
            new WorldGeneralInfo("伽约博马尔", "伽约博马鲁斯", "Gaiobomarus", "夸迪王（213年）", "狄奥记卡拉卡拉以其“被控有罪”为由将这位夸迪王处死并以此自夸（213年潘诺尼亚之役）。190年时应已成年，身份不详。显示名按拉丁人名惯例省去词尾 -us。", "作为夸迪部首领在任，隶属马科曼尼联盟。", null, 213, "yes", "german", "m"),
            new WorldGeneralInfo("阿里奥盖斯", "阿里奥盖苏斯", "Ariogaesus", "前夸迪王（约172—174年），流放者", "夸迪人废富尔提乌斯而立他为王，马可悬赏千金活捉；被俘后未加杀害，只流放到亚历山大里亚，因此作为在野人才放在亚历山大。", null, null, null, "yes", "german", "m"),
            new WorldGeneralInfo("赞提库斯", "赞提库斯", "Zanticus", "雅济吉斯王（约174—175年）", "175年亲自向马可·奥勒留乞和，交还十万俘虏、出骑兵八千；骑射与冰上作战是雅济吉斯人所长。190年是否仍在位不详。", "放宽年代收录。", null, null, "yes", "sarmatian", "m"),
            new WorldGeneralInfo("巴纳达斯普", "巴纳达斯普斯", "Banadaspus", "前雅济吉斯王（至174年）", "因私下向马可·奥勒留求和被本族废黜囚禁，由赞提库斯继位。", "忠诚偏低。", null, null, "yes", "sarmatian", "m"),
            new WorldGeneralInfo("菲利默", "菲利默（加达里克之子）", "Filimer", "哥特王（传说，约2世纪后期）", "约达尼斯《哥特史》：自贝里格以来第五代王，率哥特人南迁到斯基泰的“奥伊姆”，过河时桥断，半数族人留在对岸；又击败斯帕利人。只见于6世纪的传说史。", null, null, null, "legendary", "german", "m"),
            new WorldGeneralInfo("撒罗玛提斯", "提比略·尤利乌斯·撒罗玛提斯二世（萨夫罗马特斯二世）", "Tiberius Julius Sauromates II", "博斯普鲁斯王（约172—210年）", "罗马藩属王；约186年起与斯基泰人、西拉奇人及海盗作战，193年塔奈斯铭文称其肃清黑海航路、远达本都与比提尼亚。", null, null, 210, "yes", "sarmatian", "m"),
            new WorldGeneralInfo("雷斯库波", "提比略·尤利乌斯·雷斯库波利斯三世", "Tiberius Julius Rhescuporis III", "撒罗玛提斯二世之子（211—228年在位）", "铭文证实为撒罗玛提斯二世之子，在位事迹几乎只见于钱币。作为在野人才（王子）。", null, null, 228, "yes", "sarmatian", "m"),
            new WorldGeneralInfo("皮耶波鲁斯", "皮耶波鲁斯", "Pieporus", "科斯托博契王（2世纪，年代不确定）", "只见于罗马城一块已佚的墓碑（CIL VI 1801）：其妻、达契亚女子齐娅由孙辈在罗马安葬，家人可能是人质。年代一般放在马科曼尼战争前后。", null, null, null, "yes", "celt", "m"),
        };

