            new WorldFactionInfo("wuhuan", "乌桓", "三郡乌桓（辽西乌丸）", "Wuhuan", "丘力居", "liucheng", "steppe", "saibei", "辽西大人丘力居刚结束张纯之乱、受刘虞招抚；初平中卒，从子蹋顿代立，“总摄三王部”。190年时上谷难楼、辽东属国苏仆延（峭王）、右北平乌延（汗鲁王）都各自称王，并不隶属丘力居，此处一并并入。", null),
            new WorldFactionInfo("xiongnu", "南匈奴", "南匈奴（持至尸逐侯单于於夫罗）", "Southern Xiongnu", "於夫罗", "pingyang", "steppe", "saibei", "188年即位的於夫罗被国人拒纳，率数千骑流寓河东平阳；美稷单于庭由反对他的“老王”行国事，单于之位空缺，因此美稷不归於夫罗。195年於夫罗死，弟呼厨泉立。", null),
            new WorldFactionInfo("kroraina", "鄯善", "鄯善国（Kroraina，楼兰）", "Kroraina", "童格罗伽", "shanshan", "tarim", "xiyu", "佉卢文书显示鄯善诸王自称“大王、众王之王、天子”，仿照贵霜王号。童格罗伽是文书所见最早的国王，确切年代未定（约2世纪末至3世纪初）。", "童格罗伽的年代提前放在190年。"),
            new WorldFactionInfo("khotan", "于阗", "于阗国", "Khotan", "安国", "yutian", "tarim", "xiyu", "152年于阗王建被西域长史王敬所杀，国人立其子安国；175年安国攻破拘弥。此后史书不载于阗王名。", "沿用安国为君主。"),
            new WorldFactionInfo("kashgar", "疏勒", "疏勒国", "Kashgar (Shule)", "和得", "shule", "tarim", "xiyu", "168年和得射杀侄子、疏勒王臣磐后自立，170年汉军三万余人攻他不下；此后“疏勒王连相杀害”。", "沿用和得为君主。"),
            new WorldFactionInfo("jushi", "车师", "车师后部", "Jushi (Further Kingdom)", "阿罗多", "wutugu", "tarim", "xiyu", "车师后部王阿罗多153年反叛，后被汉朝复立。车师前部（交河）此期王名失载。", "交河设为空城。"),
            new WorldFactionInfo("shixie", "士燮", "士氏（交趾太守 士燮）", "士燮 Shi Xie / Sĩ Nhiếp", "士燮", "jiaozhi", "han", "jiaozhou", "苍梧广信人，父士赐桓帝时为日南太守。士燮举茂才、除巫令，中平四年（187）迁交趾太守。体器宽厚、谦虚下士，中原士人往依避难者以百数；朱符死后表弟士壹领合浦、士䵋领九真、士武领南海，兄弟“并为列郡，雄长一州”。210年归附孙权，226年卒，年九十。190年时只有交趾一郡属他本人。", "九真、合浦按其家族与盟友的势力范围划入。德高、人望中上。"),
            new WorldFactionInfo("zhufu", "朱符", "交趾刺史 朱符", "朱符 Zhu Fu / Chu Phù", "朱符", "cangwu", "han", "jiaozhou", "会稽人，太尉朱儁之子、豫章太守朱皓之兄。灵帝末至献帝初任交趾刺史（一说中平三年即186年接替贾琮，一说187年到任），兴平二年（195）仍在任。多以乡人虞褒、刘彦之徒分作长吏，侵虐百姓、强赋于民，“黄鱼一枚收稻一斛”，百姓怨叛、山贼并出、攻州突郡，终“走入海，流离丧亡”（卒年有195、197、203诸说）。东汉州治本在交趾龙编，与士燮所居的羸楼同郡，相距仅二十余公里。", "改以苍梧广信（203—217年的州治）为其都城。德极低、人望靠父荫。"),
            new WorldFactionInfo("linyi", "林邑", "林邑国（占婆前身）", "Lâm Ấp / Linyi (proto-Champa)", "区连", "xianglin", "seasia", "jiaozhou", "《晋书·林邑传》：“后汉末，县功曹姓区，有子曰连，杀令，自号为王，子孙相承。”《水经注》引《林邑记》系于“初平之乱”（190—193），现代通说定为192年。区连之后直到范熊（3世纪后期）王名不传。", "开局把林邑当作刚刚自立的势力（严格说早了约两年）。"),
            new WorldFactionInfo("funan", "扶南", "扶南国（混氏王朝）", "Funan / Phù Nam", "混盘况", "temu", "seasia", "jiaozhou", "《梁书·扶南传》：混填娶女王柳叶，生子分王七邑；其后王混盘况“以诈力间诸邑，令相疑阻，因举兵攻并之”，遣子孙分治诸邑，号小王；盘况年九十余乃死，中子盘盘立，以国事委大将范蔓；盘盘立三年死，国人共举蔓为王。混盘况在位于2世纪后期，190年仍是扶南王。都特牧城（毗耶陀补罗，今柬埔寨波萝勉省巴普农），外港喔㕭出土过安敦宁·庇护与马可·奥勒留时代的罗马金币。", null),
            new WorldFactionInfo("kushan", "贵霜", "贵霜帝国（大月氏）", "Kushan Empire", "胡维色迦", "purushapura", "kushan", "tianzhu", "贵霜帝国鼎盛于迦腻色伽与胡维色迦之世，疆域自巴克特里亚延至恒河流域。胡维色迦的最后纪年为迦腻色伽纪元60年（约187年），波调最早为64或67年（约191/194年），190年正处两王交替之际。", "以胡维色迦为君主、波调为继承人。可考人物极少，蓝氏城、迦毕试、塔克西拉只能设为空城。"),
            new WorldFactionInfo("kshatrapa", "西总督", "西部总督王朝（西萨特拉普·卡尔达摩王朝）", "Western Satraps (Kardamaka dynasty)", "鲁德拉辛哈", "ujjain", "kushan", "tianzhu", "塞种出身、以“总督（Kshatrapa）/大总督（Mahakshatrapa）”为号的印度西部王朝，鲁德拉达曼一世（约130—150年）之后由其子孙统治；190年由鲁德拉辛哈一世当政，但其侄吉瓦达曼另有称号之争。外观借用贵霜式装束（塞种）。", null),
            new WorldFactionInfo("parthia", "安息", "安息帝国（阿尔沙克王朝）", "Parthian (Arsacid) Empire", "沃洛吉斯", "ctesiphon", "persia", "bosi", "沃洛吉斯四世（147—191年在位）于191年卒，子沃洛吉斯五世（即亚美尼亚王瓦加尔什二世）继位。亚美尼亚由安息王储镇守；奥斯罗埃斯只见于钱币，约190年在伊朗高原自行铸币。", "亚美尼亚并入本势力；奥斯罗埃斯忠诚偏低。波西斯的巴兹兰吉藩王拆为独立势力“波西斯”，以免安息开局即成庞然大物，也为萨珊崛起留出舞台。"),
            new WorldFactionInfo("persis", "波西斯", "波西斯王国（巴兹兰吉王朝，安息藩属）", "Persis (Bazrangids)", "戈契赫尔", "istakhr", "persia", "bosi", "法尔斯（波西斯）自塞琉古时代起便由本地王公统治，安息时代为自铸钱币的藩国。据塔巴里，190年前后的波西斯王是巴兹兰吉家族的戈契赫尔，居白城（近伊斯塔克尔）；伊斯塔克尔阿娜希塔火庙的守护者萨珊、其子帕佩克与达拉布格尔德的宦官提里都在其治下。约205/206年帕佩克推翻戈契赫尔，其子阿尔达希尔后来灭亡安息、建立萨珊王朝。", "史实中是安息藩国，游戏中拆为独立势力。"),
            new WorldFactionInfo("iberia", "伊比利亚", "高加索伊比利亚王国（卡特利）", "Kingdom of Iberia (Kartli)", "列夫", "mtskheta", "persia", "bosi", "据中世纪格鲁吉亚编年史与图曼诺夫年表，阿马扎斯普二世189年被推翻，其外甥、亚美尼亚王之子列夫一世（189—216年）即位，是伊比利亚阿尔沙克王朝之始。", "只有列夫一名武将。"),
            new WorldFactionInfo("hatra", "哈特拉", "哈特拉王国（阿拉伯人之王）", "Kingdom of Hatra (ʿArab)", "阿布萨米亚", "hatra", "arab", "arab", "哈特拉统治者自萨纳特鲁克一世起称“阿拉伯人之王”，名义上是安息藩属。193年援助尼格尔，约197—199年间两度挫败塞维鲁的围攻。", null),
            new WorldFactionInfo("osroene", "奥斯若恩", "奥斯若恩王国（埃德萨）", "Kingdom of Osroene (Edessa)", "阿布加尔", "edessa", "arab", "arab", "阿布加尔八世“大王”（177—212年）在罗马与安息之间周旋；194/195年参与围攻尼西比斯，招致塞维鲁东征，王国被压缩到埃德萨一带，但他本人仍得罗马礼遇。宫廷有哲学家巴戴桑。", null),
            new WorldFactionInfo("saba", "萨巴", "萨巴王国（萨巴与祖赖丹王）", "Kingdom of Sabaʾ", "阿勒汗", "marib", "arab", "arab", "约200年前后萨巴王阿勒汗·纳赫凡与其子沙伊鲁姆·奥塔尔共治，与阿克苏姆王加达拉特订盟；沙伊鲁姆约210年后独掌王权、四出征战，是萨巴最后一位强王。南阿拉伯诸王年代学误差约二十年，阿勒汗190年是否已即位不能确定。", null),
            new WorldFactionInfo("himyar", "希木叶尔", "希木叶尔王国（祖赖丹）", "Ḥimyarite Kingdom", "塔兰", "zafar", "arab", "arab", "以扎法尔为都、与萨巴争夺“萨巴与祖赖丹王”称号的高原王国。达马尔阿里·尤哈比尔约175年传位其子塔兰·亚乌布·尤汉阿姆，塔兰独治到约214年。", "只有塔兰一名武将。"),
            new WorldFactionInfo("hadramawt", "哈德拉毛", "哈德拉毛王国", "Kingdom of Ḥaḍramawt", "伊勒阿兹", "shabwa", "arab", "arab", "乳香产地之王国，2世纪后期吞并卡塔班。约200—230年间的国王伊勒阿兹·雅卢特见于乌格拉山铭文。", "190年前后的国王名不详，放宽年代采用伊勒阿兹·雅卢特；只有他一名武将。"),
            new WorldFactionInfo("aksum", "阿克苏姆", "阿克苏姆王国", "Kingdom of Aksum", "加达拉特", "aksum", "arab", "arab", "红海西岸的埃塞俄比亚高原王国，约200年加达拉特（GDRT）开始插手也门诸国之争。", "外观暂借阿拉伯式（游戏中没有非洲文化）。"),
            new WorldFactionInfo("roma", "罗马", "罗马帝国（安敦尼王朝）", "Imperium Romanum", "康茂德", "roma", "roman", "roma", "180年起由康茂德独自统治。190年初朝政由宠臣克里安德把持，当年粮荒暴动后克里安德被处死；191年起禁卫军长官莱图斯、侍从长埃克莱图斯与情妇玛琪亚掌权，192年12月31日三人合谋将康茂德刺杀，次年即“五帝之年”。", "15座城各须有一名在任武将才能归属本势力，故在任武将较多。192年的三名弑君者（莱图斯、埃克莱图斯、玛琪亚）忠诚只有30—32，选择罗马时他们可能出奔或被他国拉拢；其余将领忠诚按史实设定。"),
            new WorldFactionInfo("caledonia", "喀里多尼亚", "喀里多尼亚人（不列颠北部诸部）", "Caledonii", "阿根托科克斯", "caledonia", "celt", "barbar", "哈德良长城以北的不列颠诸部。狄奥把他们分为喀里多尼亚人与迈阿泰人两大群；180年代曾越过长城，被乌尔皮乌斯·马克塞卢斯击退。208—210年塞维鲁北征时，狄奥记有其首领阿根托科克斯。", "190年前后无可考首领，放宽年代以阿根托科克斯为君主（只此一名武将）。"),
            new WorldFactionInfo("marcomanni", "马科曼尼", "马科曼尼—夸迪联盟（苏维汇诸部）", "Marcomanni & Quadi", "巴洛马尔", "marcomannia", "german", "barbar", "166/167年巴洛马尔代表十一个部族与潘诺尼亚总督伊阿利乌斯·巴苏斯议和，随后领导了167—170年入侵意大利的联军；马科曼尼与夸迪在马科曼尼战争中协同作战，180年与康茂德订约。", "马科曼尼与夸迪两族合为一个势力，夸迪由富尔提乌斯驻守。人物年代均放宽（166—213年），见各人物介绍。"),
            new WorldFactionInfo("iazyges", "雅济吉斯", "雅济吉斯人（萨尔马提亚）", "Iazyges", "赞提库斯", "iazyges", "sarmatian", "barbar", "居多瑙河与蒂萨河之间平原的萨尔马提亚骑马民族。175年国王赞提库斯向马可·奥勒留乞和，归还十万罗马俘虏、提供八千骑兵（其中5500人被派往不列颠）。前王巴纳达斯普斯因私通罗马被本族囚禁。", "年代放宽到约174—175年。"),
            new WorldFactionInfo("goths", "哥特", "哥特人", "Gutones / Gothi", "菲利默", "gothia", "german", "barbar", "约达尼斯《哥特史》说哥特人自斯堪札出发后第五代王菲利默率众南迁，到达斯基泰的“奥伊姆”；考古上维尔巴克文化在2世纪末扩展到维斯瓦河以东（马斯沃门奇集团）。菲利默为传说人物（attested: legendary）。250—251年击杀德西乌斯的哥特王尼瓦（克尼瓦）超出150—230年的蛮族首领窗口、生年不详，不收。", null),
            new WorldFactionInfo("bosporus", "博斯普鲁斯", "博斯普鲁斯王国（辛梅里安博斯普鲁斯）", "Regnum Bospori", "撒罗玛提斯", "panticapaeum", "sarmatian", "barbar", "以潘提卡彭（今刻赤）为都的希腊—萨尔马提亚王国，罗马藩属（国王号称“凯撒之友、罗马之友”）。撒罗玛提斯二世（约172—210年在位）约自186年起与斯基泰人、西拉奇人及海盗作战，193年塔奈斯铭文记其大胜。", null),
        };

        // 新增城池资料（SG.CityInfo，原顺序）
        public static readonly WorldCityInfo[] CityInfo =
        {
            new WorldCityInfo("xiangping", "辽东郡治 襄平县", "襄平 Xiangping", "中国辽宁省辽阳市", "公孙度本籍与治所。190年于城南设坛墠、郊祀天地，自立辽东侯；中原士人管宁、邴原、王烈、国渊等避乱多至此。（数值按《后汉书·郡国志》辽东郡口约8万、并计汉末流民涌入而定，略低于公孙瓒的北平。）", "han"),
            new WorldCityInfo("xuantu", "玄菟郡治（东汉第三/四玄菟郡，高句丽县）", "玄菟 Xuantu", "中国辽宁省沈阳市浑南区上伯官屯古城（一说抚顺劳动公园古城）", "东汉玄菟郡三迁其治，121年后在今沈阳东。北接夫余、东邻高句丽；夫余原属玄菟，汉末改属辽东。与襄平仅相距约0.7°，地图上如重叠可向东北略移。《郡国志》玄菟郡口四万余，人口取9万。", "han"),
            new WorldCityInfo("lelang", "乐浪郡治 朝鲜县（乐浪土城）", "樂浪 Lelang / 낙랑 Nangnang", "朝鲜平壤市乐浪区域（大同江南岸）", "140年前后乐浪郡户六万余、口二十五万余，汉文化在半岛的中心。公孙度兼领乐浪；204年前后公孙康分屯有县以南荒地置带方郡，遣公孙模、张敞收集遗民、伐韩濊。", "han"),
            new WorldCityInfo("guonei", "高句丽都城 国内城（卫城尉那岩城，198年扩建为丸都城）", "國內城 Gungnae-seong 국내성", "中国吉林省集安市", "3年起为高句丽都城。《三国志》称其“多大山深谷，无原泽……无良田”，户三万，故土地值偏低。209年山上王移都丸都（同在集安）。", "korea"),
            new WorldCityInfo("okjeo", "东沃沮", "東沃沮 Dong-okjeo 동옥저", "朝鲜咸镜南道咸兴一带（盖马大山之东）", "户五千，无大君王，邑落各有长帅；国小迫于大国之间，遂臣属句丽，句丽置其中大人为使者统领、责其租赋，以貊布、鱼盐、海产输国内。土地肥美，宜五谷。", "korea"),
            new WorldCityInfo("fuyu", "夫余前期王城", "夫餘 Buyeo 부여", "中国吉林省吉林市东团山·南城子古城（松花江畔）", "户八万，“于东夷之域最平敞，土地宜五谷”。考古以吉林市东团山南城子为前期王城、帽儿山为王陵区。", "korea"),
            new WorldCityInfo("dongye", "濊（东濊）", "濊 Ye / 동예 Dongye", "韩国江原道江陵市（《三国史记·地理志》所称濊国故地）", "户二万，无大君长，以侯、邑君、三老统主下户；汉末更属句丽。无可考之具名人物，按规则作中立城（无武将）。《三国志》称濊“汉末更属句丽”，190年时是否已属高句丽不明，此处作中立。", "korea"),
            new WorldCityInfo("wirye", "百济都城 河南慰礼城（汉城）", "慰禮城 Wiryeseong 위례성", "韩国首尔市松坡区风纳土城", "风纳土城一般比定为河南慰礼城，至475年为百济都城。", "korea"),
            new WorldCityInfo("mokji", "马韩 目支国（月支国，辰王治所）", "目支國 Mokji-guk 목지국", "韩国忠清南道天安市稷山一带（主流说；另有牙山、礼山、益山、罗州诸说）", "马韩五十余国、大国万余家，共推辰王治目支国。三国志只记臣智、邑借等官号，无可考之具名人物，作中立城。距慰礼城仅约0.7°。", "korea"),
            new WorldCityInfo("seorabeol", "斯卢国都 金城（王宫月城）", "徐羅伐 Seorabeol 서라벌", "韩国庆尚北道庆州市月城", "月城筑于101年。城名用“徐罗伐”而不用“金城”，以免与金城郡（今兰州）同名。", "korea"),
            new WorldCityInfo("geumgwan", "金官伽倻王都（凤凰土城）", "金官加耶 Geumgwan Gaya 금관가야", "韩国庆尚南道金海市凤凰洞遗迹", "弁辰产铁，韩、濊、倭皆来取，诸市买皆用铁；《魏志倭人传》中带方郡使经“其北岸狗邪韩国”渡海至对马，故为通倭海路的起点。产业值偏高。", "korea"),
            new WorldCityInfo("ito", "伊都国（代表北九州：伊都、奴、末卢、不弥及对马、一支）", "伊都国 Ito-koku いとこく", "日本福冈县糸岛市三云·井原遗迹", "“世有王，皆统属女王国，郡使往来常所驻”；女王国以北特置一大率常治伊都国。邻近的奴国（二万余户，今福冈市）仅隔约25公里，合并入此城。", "wa"),
            new WorldCityInfo("touma", "投马国（此处比定为吉备）", "投馬国 Tsuma-koku つまこく", "日本冈山县仓敷市楯筑遗迹一带（吉备）", "可五万余户，官曰弥弥、副曰弥弥那利。比定地众说纷纭（吉备、出云、但马、鞆、日向……）。畿内说下取吉备：濑户内海航路要冲，楯筑坟丘墓为弥生后期最大，其特殊器台见于缠向与箸墓，吉备被视为共立卑弥呼的一方。", "wa"),
            new WorldCityInfo("yamatai", "邪马台国（女王之所都）", "邪馬台国 Yamatai-koku やまたいこく", "日本奈良县樱井市缠向遗迹（三轮山西北麓）", "可七万余户。缠向遗迹为2世纪末至4世纪的大型聚落，邻近箸墓古坟（3世纪中叶，有卑弥呼墓之说）；取畿内说。", "wa"),
            new WorldCityInfo("kuna", "狗奴国（此处比定为浓尾平原）", "狗奴国 Kuna-koku くなこく", "日本爱知县清须市朝日遗迹（东海最大的弥生环濠聚落）", "畿内说下，狗奴国为以浓尾平原为中心、前方后方坟流行的东日本势力（白石太一郎、赤塚次郎等）。九州说则比定为熊本（球磨、菊池）。", "wa"),
            new WorldCityInfo("taiwan", "夷洲（台湾）", "夷洲 Yizhou (Taiwan)", "台湾新北市八里区十三行遗址（淡水河口南岸）", "尚无国家，诸部落散居；十三行文化约始于1800年前，属铁器时代且能炼铁。230年孙权遣卫温、诸葛直率甲士万人浮海求夷洲，得数千人而还；沈莹《临海水土志》最早描写其风俗。无具名本地人物，作中立城（无武将）。", "yi"),
            new WorldCityInfo("danhan", "弹汗山·歠仇水（鲜卑王庭）", "Danhan Mountain", "河北尚义—内蒙古商都、兴和一带（东洋河上源）", "檀石槐“立庭于弹汗山歠仇水上，去高柳北三百余里”；具体位置有尚义大青山、商都等说法。魁头时期是否仍以此为庭，史无明文。", "steppe"),
            new WorldCityInfo("raole", "饶乐水（东部鲜卑牧地）", "Raole River (Xar Moron)", "内蒙古赤峰一带，西拉木伦河—老哈河流域", "《后汉书》说鲜卑“以季春月大会于饶乐水上”；饶乐水即西拉木伦河，在北纬43.3°上下东流，至翁牛特旗与奈曼旗交界处汇老哈河。素利、弥加、厥机在辽西、右北平、渔阳塞外，取这一带作为节点。", "steppe"),
            new WorldCityInfo("liucheng", "辽西柳城（乌桓王庭）", "Liucheng", "辽宁朝阳", "三郡乌桓以柳城为政治中心；207年曹操在柳城附近的白狼山斩杀蹋顿。", "steppe"),
            new WorldCityInfo("ningcheng", "上谷宁城（护乌桓校尉府·胡市）", "Ningcheng (Shanggu)", "河北张家口（一说怀来）", "东汉护乌桓校尉的治所，也是与乌桓、鲜卑互市的地方；上谷乌桓难楼九千余落聚居在这一带塞内外。城本身是汉式城郭。", "han"),
            new WorldCityInfo("meiji", "西河美稷（南匈奴单于庭）", "Meiji", "内蒙古准格尔旗纳林古城", "50年南单于庭迁到美稷；140年西河郡治南迁离石后，单于庭是否随迁有争议。189年须卜骨都侯死后由“老王”行国事，拒不接纳於夫罗，因此190年设为空城（不归於夫罗）。", "steppe"),
            new WorldCityInfo("pingyang", "河东平阳（於夫罗驻地）", "Pingyang", "山西临汾", "於夫罗“复欲归国，国人不受，乃止河东平阳”；此后数十年这里一直是南匈奴的中心。", "han"),
            new WorldCityInfo("yinshan", "阴山北麓（西部鲜卑牧地）", "Yin Mountains", "内蒙古包头以北、达茂—固阳一带", "檀石槐时“从上谷以西至敦煌、乌孙”是西部，大人有置鞬落罗、日律推演、宴荔游等；190年时的首领不详，设为空城。拓跋部后来也从这一带南下。", "steppe"),
            new WorldCityInfo("dingling", "丁零（贝加尔湖以南、色楞格河流域）", "Dingling", "俄罗斯布里亚特—蒙古北部色楞格河流域", "85年丁零与鲜卑、南匈奴合击北匈奴；《魏略》记有丁令国“胜兵六万人”。这一时期没有见于记载的人名，设为空城。", "steppe"),
            new WorldCityInfo("jiankun", "坚昆（叶尼塞河上游）", "Jiankun (Kyrgyz)", "俄罗斯米努辛斯克盆地", "《魏略》说坚昆国“胜兵三万人”；汉代坚昆在叶尼塞河上游，以铁器著称。没有见于记载的人名，设为空城。", "steppe"),
            new WorldCityInfo("dunhuang", "敦煌郡", "Dunhuang", "甘肃敦煌", "汉郡，《郡国志》户748、口29170（少于武威郡的口34226）。190年太守名字不详，凉州诸郡在羌乱中与朝廷隔绝；《仓慈传》说“郡在西陲，以丧乱隔绝，旷无太守二十岁，大姓雄张”。马腾、韩遂并没有控制这里，因此设为空城。", "han"),
            new WorldCityInfo("yiwu", "伊吾（宜禾都尉屯田）", "Yiwu (Hami)", "新疆哈密", "东汉北道上的要冲，曾设伊吾司马、宜禾都尉屯田；190年时无人驻守的记载，设为空城。", "tarim"),
            new WorldCityInfo("loulan", "楼兰城（海头，魏晋西域长史府）", "Kroraina (LA)", "新疆若羌县罗布泊西北楼兰古城", "东汉、魏晋时西域长史的驻地之一（一般认为曹魏于222年前后重置西域长史，治楼兰海头；但《文帝纪》只明载222年置戊己校尉），属鄯善国境。190年无人驻守的记载，设为空城。", "tarim"),
            new WorldCityInfo("shanshan", "鄯善国都扜泥城", "Kuhani / Yuni", "新疆若羌县（扜泥城的位置有若羌、楼兰LA、米兰等说）", "鄯善在东汉吞并了小宛、精绝、戎卢、且末，成为南道大国（《汉书》时本国仅口14100）；扜泥城的具体位置有争议。", "tarim"),
            new WorldCityInfo("jingjue", "精绝（Cadota，尼雅遗址）", "Cadota (Niya)", "新疆民丰县北尼雅遗址", "《汉书》记精绝户480、口3360，东汉时已被鄯善吞并；3世纪大批佉卢文书出土于此。游戏中设为空城，等待鄯善收复。", "tarim"),
            new WorldCityInfo("yutian", "于阗国都西城", "Khotan", "新疆和田（约特干遗址）", "南道大国，《后汉书》记载“户三万二千，口八万三千，胜兵三万余人”；以出产美玉闻名。", "tarim"),
            new WorldCityInfo("shule", "疏勒国都", "Kashgar", "新疆喀什", "葱岭以东的门户，向西通大宛、大月氏；170年汉军围攻桢中城失败。", "tarim"),
            new WorldCityInfo("qiuci", "龟兹国都延城", "Kucha", "新疆库车（皮朗古城）", "北道大国，冶铁发达。白英（约110—127年在位）之后，到西晋白山（约280年）之间的国王名字均失载，设为空城。", "tarim"),
            new WorldCityInfo("yanqi", "焉耆国都员渠城", "Karasahr (Agni)", "新疆焉耆（博格达沁古城）", "《后汉书》记焉耆户15000、口52000、胜兵二万余。元孟（94—127年）之后，到西晋龙安（约285年）之间的国王名字均失载，设为空城。", "tarim"),
            new WorldCityInfo("jiaohe", "交河城（车师前部王庭）", "Jiaohe (Yarkhoto)", "新疆吐鲁番交河故城", "车师前王治交河城，《后汉书》记其户1500余、口4000余、胜兵2000；附近的高昌壁是戊己校尉驻地。此期前部王名失载，设为空城。", "tarim"),
            new WorldCityInfo("wutugu", "车师后部王庭（务涂谷 / 于赖城）", "Jushi Further Kingdom", "新疆吉木萨尔县南", "《后汉书》说后部王居务涂谷，户4000余、口15000余、胜兵3000余；《魏略》作于赖城；车师古道向南翻越天山可到交河。", "tarim"),
            new WorldCityInfo("wusun", "乌孙国都赤谷城", "Wusun (Chigu)", "吉尔吉斯斯坦伊塞克湖东岸（一说纳伦河上游）", "汉代口数六十三万，是西域人口最多的国家；东汉以后大小昆弥分治，国势衰弱，此期王名失载，设为空城。", "steppe"),
            new WorldCityInfo("kangju", "康居国（卑阗城）", "Kangju", "乌兹别克斯坦塔什干一带（卑阗城的位置未定）", "《魏略》说康居“本国无增损”；北匈奴余部约160—260年在康居境内活动。王名失载，设为空城。可能与贵霜区重复，请按 key 合并。", "kushan"),
            new WorldCityInfo("dayuan", "大宛国都贵山城", "Dayuan (Ferghana)", "费尔干纳盆地（卡散赛或苦盏）", "出产汗血马，有七十余城；晋太康六年（285年）才有大宛王蓝庾的记载，此期王名失载，设为空城。可能与贵霜区重复。", "kushan"),
            new WorldCityInfo("panyu", "南海郡治 番禺县", "番禺 Panyu", "中国广东省广州市越秀区（南越国宫署遗址一带）", "南越国故都、岭南最大海港，续汉志载南海郡口250,282。210年步骘率军抵番禺，217年州治由广信移此。城名用“番禺”而不用“南海”，以免与海名混淆。", "han"),
            new WorldCityInfo("cangwu", "苍梧郡治 广信县", "广信 Guangxin (Cangwu)", "中国广西梧州市（一说广东封开县）——漓水与郁水（西江）交汇处", "士燮的故乡。续汉志载苍梧郡口466,975，为交州七郡之冠（交趾郡无数）。203年交趾刺史部改称交州，州治在此至217年；刘表所遣赖恭、吴巨均驻此。游戏中作为朱符的都城（史实州治在交趾龙编）。", "han"),
            new WorldCityInfo("hepu", "合浦郡治 合浦县", "合浦 Hepu", "中国广西北海市合浦县廉州镇草鞋村汉城遗址", "“合浦珠还”的产珠之郡、汉代海上丝路始发港之一（辖徐闻、合浦、高凉、临允、朱卢五县）。续汉志载郡口86,617，故土地、粮食低而产业、金钱偏高。士䵋在朱符死时任本郡徐闻令（190年是否已在任不详），朱符死后士壹领合浦太守。", "han"),
            new WorldCityInfo("jiaozhi", "交趾郡（东汉郡治、州治在龙编；士燮治所相传在羸楼）", "羸楼 Luy Lâu (Giao Chỉ)", "越南北宁省顺成县清姜社羸楼古城（河内以东约30公里）", "红河三角洲的稻作中心、交州人口最多之郡（西汉时口七十四万余）。士燮在此治理四十年，“出入鸣钟磬，备具威仪……胡人夹毂焚烧香者常有数十”；羸楼同时是早期佛教传入中国的南路据点（牟子、康僧会）。", "han"),
            new WorldCityInfo("jiuzhen", "九真郡治 胥浦县", "胥浦 Tư Phố (Cửu Chân)", "越南清化省清化市西北（马江下游）", "续汉志载九真郡口209,894。190年前后太守儋萌在任，后为郡吏番苗所杀，士燮遣兵讨之不克；朱符死后士䵋领九真太守。", "han"),
            new WorldCityInfo("rinan", "日南郡治 西卷县", "西卷 Tây Quyển (Nhật Nam)", "越南广治省东河市一带", "汉朝最南的郡，166年“大秦王安敦”的使者即“自日南徼外”来献象牙、犀角、玳瑁。190年前后的日南太守姓名不传，故设为中立城；南部象林县已被区连夺去。", "han"),
            new WorldCityInfo("xianglin", "日南郡象林县 → 林邑国都", "象林 Tượng Lâm", "越南广南省维川县茶荞（会安西南）", "区连杀县令、自立为王之地，后来林邑都城僧伽补罗（茶荞）也在此。一说汉象林县治在今顺化附近，此取广南茶荞说。", "seasia"),
            new WorldCityInfo("temu", "扶南都城 特牧城", "Vyādhapura（毗耶陀补罗，“猎人之城”）", "柬埔寨波萝勉省巴普农县（巴普农山附近）", "新唐书称扶南“治特牧城”；现代学者比定为巴普农的毗耶陀补罗，相传为混盘况所建。湄公河下游的稻作腹地。", "seasia"),
            new WorldCityInfo("oceo", "扶南外港（喔㕭遗址）", "Óc Eo", "越南安江省梭山县喔㕭社（巴提山下）", "扶南最大的港市，经运河与内地相连；出土罗马安敦宁·庇护、马可·奥勒留金币、汉镜、印度造像与波斯玻璃珠，或即托勒密所记的 Kattigara。汉文古籍未载其名，“喔㕭”是越南语地名的今译。", "seasia"),
            new WorldCityInfo("dunxun", "顿逊国（典孙）", "Tun Sun / Dunxun", "克拉地峡（取东岸春蓬府考山三乔古港；中文维基比定为缅甸丹那沙林）", "《梁书》：扶南“南界三千余里有顿逊国，在海崎上，地方千里……有五王，并羁属扶南。顿逊之东界通交州，其西界接天竺、安息徼外诸国，往还交市……日有万余人”。为范师蔓所征服的“典孙”，190年尚独立；王名不传，设为中立城。考山三乔为公元前4世纪至公元初年的地峡港市。", "seasia"),
            new WorldCityInfo("jinlin", "金邻国（金陈）", "Jinlin / Chin Lin（“金地” Suvarṇabhūmi）", "泰国素攀武里府乌通古城（Wheatley 说；另有佛统、叻丕及缅甸直通—马达班诸说）", "《南州异物志》：“金邻一名金陈，去扶南可二千余里。地出银，人民多好猎大象。”范师蔓欲伐金邻时病卒。孟人（堕罗钵底前身）的湄南河流域中心，190年君主名不传，设为中立城。", "seasia"),
            new WorldCityInfo("langyaxiu", "狼牙修国", "Langkasuka", "泰国北大年府耶冷县古城遗址（距海约15公里）", "《梁书》称其515年时“立国以来四百余年”，即约2世纪初立国；最早可考的王名婆伽达多已在6世纪。190年无可考人物，设为中立城。", "seasia"),
            new WorldCityInfo("purushapura", "富楼沙（弗楼沙、布路沙布逻）", "Puruṣapura", "巴基斯坦白沙瓦", "贵霜冬都与犍陀罗中心，迦腻色伽在此建大塔（雀离浮图）；越开伯尔山口西通迦毕试。", "kushan"),
            new WorldCityInfo("bactra", "蓝氏城（巴克特拉，大夏故都）", "Bactra", "阿富汗巴尔赫", "《后汉书》大月氏“居蓝氏城”；巴克特里亚首府与贵霜铸币地，越葱岭通疏勒、北通粟特。实为贵霜领土，但190年无可考人物驻守，按规则设为空城。", "kushan"),
            new WorldCityInfo("kapisa", "迦毕试（贝格拉姆）", "Kāpiśī", "阿富汗贝格拉姆", "贵霜夏都；贝格拉姆宝藏同出汉地漆器、罗马玻璃与印度象牙，是兴都库什南北的枢纽。贵霜领土，因无可考人物设为空城。", "kushan"),
            new WorldCityInfo("taxila", "塔克西拉（呾叉始罗）", "Takṣaśilā", "巴基斯坦塔克西拉（锡尔卡普遗址）", "犍陀罗东部古城，丝路南下印度的要冲；经罽宾、悬度通于阗。贵霜领土，因无可考人物设为空城（草原西域研究区的 jibin 罽宾可对应此城）。", "kushan"),
            new WorldCityInfo("mathura", "秣菟罗（马图拉）", "Mathurā", "印度北方邦马图拉", "贵霜在恒河流域的中心，出土大量胡维色迦、波调纪年铭文与马特村王族祠庙；佛教与印度教造像艺术重镇。", "kushan"),
            new WorldCityInfo("samarkand", "撒马尔罕（马拉坎达，粟弋）", "Marakanda", "乌兹别克斯坦撒马尔罕（阿弗拉西阿卜）", "粟特中心，《后汉书》“粟弋国属康居”。190年无可考统治者，设为空城。", "kushan"),
            new WorldCityInfo("ujjain", "乌贾因（邬阇衍那）", "Ujjayinī", "印度中央邦乌贾因", "西部总督王朝都城，托勒密称“奥泽内，提亚斯塔内斯（查斯塔纳）的王都”；北通秣菟罗，西南下巴里加扎港。", "kushan"),
            new WorldCityInfo("barygaza", "巴里加扎（跋禄羯呫婆，今布罗奇）", "Barygaza (Bharukaccha)", "印度古吉拉特邦布罗奇", "《厄立特里亚海周航记》所载印度西岸最大港口，乌贾因货物由此出海，通波斯湾、南阿拉伯与罗马埃及。", "kushan"),
            new WorldCityInfo("ctesiphon", "泰西封（斯宾）—塞琉西亚", "Ctesiphon / Seleucia", "伊拉克萨尔曼帕克", "安息冬都，一般比定为《后汉书·西域传》的“斯宾国”；与底格里斯河对岸的希腊城市塞琉西亚合为一城（两城相距不足一公里，不另设）。165年两城被阿维狄乌斯·卡西乌斯焚掠，此时仍在恢复。", "persia"),
            new WorldCityInfo("ecbatana", "埃克巴坦那（阿蛮）", "Ecbatana", "伊朗哈马丹", "米底故都、安息夏都与主要铸币场，一般比定为《后汉书·西域传》的“阿蛮国”；呼罗珊大道由此东去。", "persia"),
            new WorldCityInfo("hecatompylos", "和椟城（赫卡通皮洛斯，“百门城”）", "Hekatompylos", "伊朗达姆甘西南沙赫雷库米斯", "安息早期王都，《后汉书》“安息国居和椟城”一般比定于此。190年时已非政治中心，亦无可考守将，设为空城。", "persia"),
            new WorldCityInfo("merv", "木鹿城（马尔吉亚纳的安条克）", "Merv (Margiana)", "土库曼斯坦马雷附近梅尔夫遗址", "马尔吉亚纳绿洲中心，《后汉书》“木鹿城，号为小安息”。有自铸钱币的藩王，但190年前后王名失载，设为空城。", "persia"),
            new WorldCityInfo("susa", "苏萨（埃利迈斯）", "Susa (Elymais)", "伊朗胡齐斯坦舒什", "埃利迈斯王国的主要城市，该国在安息宗主下自铸钱币，190年在位者钱币学上无法确定，设为空城；215年石碑记有苏萨总督霍瓦萨克。", "persia"),
            new WorldCityInfo("charax", "查拉克斯·斯帕西努（卡拉塞尼／梅塞内都城）", "Charax Spasinou", "伊拉克巴士拉以北（杰贝勒海亚巴尔）", "卡拉塞尼王国都城，位于两河入海口，帕尔米拉商队与印度航船在此交汇。151年沃洛吉斯四世击败其王米特里达梯（梅雷达特），另立奥拉巴泽斯二世；190年在位者无法确定，设为空城。", "arab"),
            new WorldCityInfo("arbela", "阿尔贝拉（阿迪亚贝纳都城）", "Arbela (Adiabene)", "伊拉克埃尔比勒", "阿迪亚贝纳王国都城。194/195年阿迪亚贝纳人与奥斯若恩人一同围攻尼西比斯，塞维鲁因而征讨，但史书未记国王名字（《阿尔贝拉编年史》真伪有争议，不采用），设为空城。", "persia"),
            new WorldCityInfo("istakhr", "伊斯塔克尔（波西斯）", "Istakhr (Persis)", "伊朗法尔斯省波斯波利斯以北", "波西斯（法尔斯）中心，阿娜希塔火庙所在，萨珊家族世代为火庙守护者；巴兹兰吉王居附近的白城（拜达），游戏中合并于此。", "persia"),
            new WorldCityInfo("darabgerd", "达拉布格尔德（达拉卜吉尔德）", "Darabgerd", "伊朗法尔斯省达拉布西南", "波西斯东南的圆形城市，城堡长官提里在此抚养少年阿尔达希尔，阿尔达希尔后来继任此地长官并由此起家。", "persia"),
            new WorldCityInfo("artaxata", "阿尔塔沙特（亚美尼亚王都）", "Artaxata (Artashat)", "亚美尼亚阿尔塔沙特（霍尔维拉普附近）", "亚美尼亚王都。163年罗马将军斯塔提乌斯·普里斯库斯毁城，在附近另建卡伊内波利斯（瓦加尔沙帕特）。此时由安息王子瓦加尔什（亚美尼亚王）统治。", "persia"),
            new WorldCityInfo("hatra", "哈特拉", "Hatra (Ḥaṭrā)", "伊拉克尼尼微省哈特尔", "沙漠中的圆形要塞与太阳神庙之城；117年图拉真、约197—199年间塞维鲁两度围攻均告失败，240/241年为萨珊沙普尔一世所破。", "arab"),
            new WorldCityInfo("edessa", "埃德萨（乌尔法）", "Edessa (Urhay)", "土耳其尚勒乌尔法", "奥斯若恩王国都城，叙利亚语文学与早期基督教中心；195年后周边地区成为罗马行省，王国只剩埃德萨城周围。201年遭大洪水。", "arab"),
            new WorldCityInfo("mtskheta", "姆茨赫塔（阿尔马齐）", "Mtskheta (Armazi)", "格鲁吉亚姆茨赫塔", "高加索伊比利亚（卡特利）王都，附近阿尔马齐城堡出土希腊—阿拉米双语铭文；北控达里尔山口（阿兰人南下之路）。", "persia"),
            new WorldCityInfo("marib", "马里卜（萨巴故都）", "Maryab (Mārib)", "也门马里卜（旧城）", "萨巴故都，马里卜大坝灌溉的绿洲，阿尔马卡神庙（阿瓦姆庙）所在；乳香之路北上纳季兰、佩特拉。【合并】萨那（萨巴的另一座城）与本城在地图上相距不足 3 单位，并入本城，沙伊鲁姆移驻马里卜。", "arab"),
            new WorldCityInfo("zafar", "扎法尔（祖赖丹）", "Ẓafār (Raydān)", "也门伊卜省雅里姆附近", "希木叶尔王国都城，王宫名“赖丹”，故其王号“祖赖丹”；南下红海港口穆扎、亚丁。", "arab"),
            new WorldCityInfo("shabwa", "沙布瓦（舍卜沃）", "Shabwat", "也门舍卜沃省沙布瓦遗址", "哈德拉毛王国都城，乳香集散地；外港卡内（今比尔阿里）乘季风通印度巴里加扎。", "arab"),
            new WorldCityInfo("aksum", "阿克苏姆（外港阿杜利斯）", "Aksum", "埃塞俄比亚提格雷州阿克苏姆", "阿克苏姆王国都城，外港阿杜利斯隔红海与也门相望（地图上不另设）。", "arab"),
            new WorldCityInfo("roma", "罗马（永恒之城）", "Roma", "意大利罗马", "帝国首都，人口约百万，靠埃及与阿非利加的海运谷物供养；按题目与洛阳同级。190年在此爆发粮荒暴动。", "roman"),
            new WorldCityInfo("lugdunum", "卢格杜努姆（高卢首府）", "Lugdunum", "法国里昂", "卢格杜努姆高卢行省首府、“三高卢”议事会所在地与帝国铸币厂；塞维鲁186—189年在此任总督，卡拉卡拉188年生于此。197年塞维鲁与阿尔拜努斯在城外决战。", "roman"),
            new WorldCityInfo("colonia", "科洛尼亚·阿格里皮嫩西姆（科隆）", "Colonia Claudia Ara Agrippinensium", "德国科隆", "下日耳曼行省首府，莱茵河下游舰队与两个军团（波恩、克桑滕）所在；对岸即自由日耳曼尼亚。", "roman"),
            new WorldCityInfo("londinium", "伦迪尼乌姆（不列颠首府）", "Londinium", "英国伦敦", "不列颠行省首府与最大港口，总督驻地；统辖三个军团，是阿尔拜努斯195—197年称帝的本钱。", "roman"),
            new WorldCityInfo("eboracum", "埃博拉库姆（约克）", "Eboracum", "英国约克", "第六胜利军团大本营，北方边防重镇；塞维鲁208—211年北征喀里多尼亚时以此为行在，并病逝于此。", "roman"),
            new WorldCityInfo("carnuntum", "卡农图姆（上潘诺尼亚首府）", "Carnuntum", "奥地利彼得罗内尔—卡农图姆", "上潘诺尼亚行省首府、第十四双子军团驻地，多瑙河“琥珀之路”渡口；马可·奥勒留曾在此指挥马科曼尼战争，193年4月塞维鲁在此被拥立为帝。", "roman"),
            new WorldCityInfo("sirmium", "西尔米乌姆（下潘诺尼亚）", "Sirmium", "塞尔维亚斯雷姆斯卡米特罗维察", "萨瓦河畔重镇，属下潘诺尼亚行省，扼多瑙河中游与巴尔干大道；马可·奥勒留在此接见雅济吉斯使节。下潘诺尼亚总督本驻阿昆库姆（布达佩斯），本图合并于此。", "roman"),
            new WorldCityInfo("byzantium", "拜占庭", "Byzantium", "土耳其伊斯坦布尔", "扼博斯普鲁斯海峡的色雷斯希腊城市；193年站在尼格尔一方，被塞维鲁军围困两年多后攻陷。本图同时代表色雷斯与下默西亚方向。", "roman"),
            new WorldCityInfo("ancyra", "安基拉（加拉太首府）", "Ancyra", "土耳其安卡拉", "加拉太行省首府，小亚细亚内陆交通枢纽；东通卡帕多细亚与萨塔拉军团营地、亚美尼亚。法比乌斯·奇洛约189—192年任加拉太总督。", "roman"),
            new WorldCityInfo("ephesus", "以弗所（亚细亚行省首府）", "Ephesus", "土耳其塞尔丘克", "亚细亚行省首府与爱琴海东岸最大商港，阿尔忒弥斯神庙所在；元老院行省，由资深执政官任总督。", "roman"),
            new WorldCityInfo("antioch", "奥龙特斯河畔安条克（叙利亚首府）", "Antiochia ad Orontem", "土耳其安塔基亚", "叙利亚行省首府、帝国东方第一大城与对安息作战的大本营；总督统辖三个军团。193年尼格尔在此称帝。", "roman"),
            new WorldCityInfo("palmyra", "帕尔米拉（塔德莫尔）", "Palmyra / Tadmor", "叙利亚塔德穆尔", "叙利亚沙漠中的绿洲商城，属罗马叙利亚行省但享有自治；商队经杜拉—欧罗普斯沿幼发拉底河通往安息的沃洛加西亚与查拉克斯，城中“将军”率骑射手护卫商路。", "arab"),
            new WorldCityInfo("alexandria", "亚历山大里亚（埃及首府）", "Alexandria", "埃及亚历山大港", "帝国第二大城、埃及长官驻地；埃及谷物经此海运罗马。红海诸港（贝勒尼基、米奥斯霍尔莫斯）通阿克苏姆、阿拉伯与印度，本图并入此城。", "roman"),
            new WorldCityInfo("carthago", "迦太基（阿非利加首府）", "Carthago", "突尼斯迦太基", "阿非利加资深执政官行省首府，帝国粮仓之一；佩蒂纳克斯、尤利安努斯、阿努利努斯先后在此任总督。", "roman"),
            new WorldCityInfo("tarraco", "塔拉科（近西班牙首府）", "Tarraco", "西班牙塔拉戈纳", "塔拉科西班牙行省首府，总督兼领驻莱昂的第七双子军团。", "roman"),
            new WorldCityInfo("caledonia", "喀里多尼亚（泰河以北）", "Caledonia", "英国苏格兰泰赛德—斯特拉思莫尔一带", "安东尼长城以北的高地与泰河流域，喀里多尼亚人的地盘；无固定都城，坐标取泰河流域（因赫图希尔罗马旧营附近）。【合并】迈阿泰（Maeatae，安东尼长城以北）与本城在地图上相距不足 3 单位，并入本城。", "celt"),
            new WorldCityInfo("marcomannia", "马科曼尼人之地（波希米亚）", "Marcomanni (Boiohaemum)", "捷克波希米亚中部", "波希米亚盆地，马科曼尼人自公元前后定居于此；无可考都城，坐标取波希米亚中部。", "german"),
            new WorldCityInfo("quadia", "夸迪人之地（摩拉维亚—斯洛伐克西部）", "Quadi", "斯洛伐克西部瓦赫河谷", "多瑙河以北、正对卡农图姆与布里格提奥的夸迪人地盘；179年罗马军曾深入至劳加里西奥（今特伦钦）越冬。坐标为大致位置。【移位】为与卡农图姆拉开距离，城址取格拉努阿河（今赫龙河）谷——马可·奥勒留《沉思录》卷一“写于夸迪人中，格拉努阿河畔”。", "german"),
            new WorldCityInfo("iazyges", "雅济吉斯人之地（多瑙河—蒂萨河间）", "Iazyges", "匈牙利大平原（多瑙河—蒂萨河之间）", "潘诺尼亚与达契亚之间的大平原，萨尔马提亚骑兵的牧地；175年和约要求他们远离多瑙河。坐标为大致位置。", "sarmatian"),
            new WorldCityInfo("gothia", "哥特人之地（维斯瓦河以东）", "Gothi (Wielbark / Masłomęcz group)", "波兰赫鲁别舒夫盆地（马斯沃门奇）", "2世纪末维尔巴克文化（哥特人）从波美拉尼亚南迁，在赫鲁别舒夫盆地形成马斯沃门奇集团，是南下黑海北岸的前哨；坐标取马斯沃门奇遗址。", "german"),
            new WorldCityInfo("costoboci", "科斯托博契与自由达契亚人之地", "Costoboci / Dacia libera", "罗马尼亚摩尔达维亚北部", "喀尔巴阡山以东的达契亚系部族；170年科斯托博契人一路劫掠到希腊厄琉息斯，约171年又遭阿斯丁吉汪达尔人重创。182—183年罗马还与“自由达契亚人”作战（尼格尔、阿尔拜努斯在此立功）。无190年可考首领，设空城；国王皮耶波鲁斯为在野。", "celt"),
            new WorldCityInfo("panticapaeum", "潘提卡彭（博斯普鲁斯王都）", "Panticapaeum", "克里米亚刻赤", "刻赤海峡西岸的希腊古城、博斯普鲁斯王都，向罗马军队与黑海南岸输出谷物与鱼；顿河口的塔奈斯也属本国，未单设。", "sarmatian"),
            new WorldCityInfo("yancai", "奄蔡（阿兰聊，阿兰人之地）", "Alani", "俄罗斯顿河—伏尔加河间草原（卡尔梅克一带）", "《后汉书》：“奄蔡国改名阿兰聊国”。阿兰人135年曾越高加索劫掠亚美尼亚、卡帕多细亚，被阿里安击退；150—230年无可考首领，设为空城。坐标只是大致位置；", "sarmatian"),
        };

        static System.Collections.Generic.Dictionary<string, WorldGeneralInfo> gIndex;
        static System.Collections.Generic.Dictionary<string, WorldFactionInfo> fIndex;
        static System.Collections.Generic.Dictionary<string, WorldCityInfo> cIndex;
        // 按名 / 键查资料；没有（经典条目）时为 null
        public static WorldGeneralInfo InfoOfGeneral(string name)
        {
            if (gIndex == null) { var d = new System.Collections.Generic.Dictionary<string, WorldGeneralInfo>(); foreach (var x in GeneralInfo) d[x.Name] = x; gIndex = d; }
            WorldGeneralInfo r; return name != null && gIndex.TryGetValue(name, out r) ? r : null;
        }
        public static WorldFactionInfo InfoOfFaction(string key)
        {
            if (fIndex == null) { var d = new System.Collections.Generic.Dictionary<string, WorldFactionInfo>(); foreach (var x in FactionInfo) d[x.Key] = x; fIndex = d; }
            WorldFactionInfo r; return key != null && fIndex.TryGetValue(key, out r) ? r : null;
        }
        public static WorldCityInfo InfoOfCity(string key)
        {
            if (cIndex == null) { var d = new System.Collections.Generic.Dictionary<string, WorldCityInfo>(); foreach (var x in CityInfo) d[x.Key] = x; cIndex = d; }
            WorldCityInfo r; return key != null && cIndex.TryGetValue(key, out r) ? r : null;
        }
    }
}
